  color: var(--text);
}

.tools-btn-soft:hover {
  background: rgba(0, 0, 0, 0.08);
  transform: translateY(-1px);
}

.tools-btn-primary {
  min-height: var(--primary-action-min-height);
  padding: var(--primary-action-padding-y) var(--primary-action-padding-x);
  border-radius: var(--primary-action-radius);
  font-size: var(--primary-action-font-size);
  font-weight: var(--primary-action-font-weight);
  gap: var(--primary-action-gap);
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
