/* Workspace + Mushaf tokens — scoped to memorisation only. Global --bg/--accent
   come from app.scss; do not redeclare them on :root (vue-styles loads globally). */
body.memorisation-page {
  --navbar-offset: 64px;
  --tools-width: 440px;
  --tools-footer-h: 78px;
  --font-ar: 'Amiri', 'Noto Naskh Arabic', 'Scheherazade New', serif;
  --font-ui: "SF Pro Text", "SF Pro Display", "Avenir Next", "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
  --font-surah-latin: "Source Serif 4", "Iowan Old Style", "Palatino Linotype", Palatino, "Noto Serif", ui-serif, Georgia, serif;
  --font-surah-arabic: "Amiri", "Noto Naskh Arabic", "Scheherazade New", serif;
  --primary-action-radius: 999px;
  --primary-action-min-height: 2.45rem;
  --primary-action-padding-y: 0.45rem;
  --primary-action-padding-x: 0.85rem;
  --primary-action-font-size: 0.8rem;
  --primary-action-font-weight: 520;
  --primary-action-gap: 0.4rem;
  --motion-fast: 150ms;
  --motion-base: 200ms;
  --motion-enter: 220ms;
  --motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --motion-press-scale: 0.97;
}

html[data-theme="light"] body.memorisation-page {
  --zone-canvas: var(--bg);
  --zone-reading-cream: var(--surface-strong);
  /* Match page chrome to --bg (surface-soft was #f3f0ea vs bg #f6f3ee banding). */
  --zone-chrome-cream: var(--bg);
  --zone-reading: var(--zone-reading-cream);
  --zone-chrome: var(--bg);
  --workspace-card-surface:
    radial-gradient(circle at top right, color-mix(in srgb, var(--accent) 10%, transparent), transparent 34%),
    linear-gradient(165deg, color-mix(in srgb, var(--zone-chrome-cream) 90%, white 10%), var(--zone-chrome-cream));
  --toolbar-header-bg: var(--workspace-card-surface);
  --toolbar-header-bg-solid: var(--zone-chrome-cream);
  --toolbar-header-border: var(--zone-divider);
  --toolbar-control-bg: var(--surface-strong);
  --toolbar-control-hover-bg: color-mix(in srgb, var(--zone-chrome-cream) 70%, var(--surface-strong));
  --toolbar-control-active-bg: var(--text);
  --toolbar-control-active-fg: var(--surface-strong);
  --toolbar-control-border: color-mix(in srgb, var(--text) 10%, transparent);
  --toolbar-control-fg: var(--text);
  --toolbar-control-muted-bg: color-mix(in srgb, var(--surface-strong) 72%, transparent);
  --mushaf-reading-surface: var(--surface-strong);
  --mushaf-reading-ink: var(--text);
  --ayah-mark-ink: var(--text);
  --zone-panel: var(--bg);
  --zone-elevated: var(--surface-strong);
  --zone-action: color-mix(in srgb, var(--bg) 92%, var(--accent) 8%);
  --zone-divider: var(--border);
}

html[data-theme="light"] body.memorisation-page .tools-top {
  background: var(--zone-chrome);
  box-shadow: none;
}

html[data-theme="dark"] body.memorisation-page {
  --zone-canvas: var(--bg);
  --zone-reading: #1a1714;
  --zone-chrome: #221d19;
  --zone-panel: #1e1a17;
  --zone-elevated: #2a2521;
  --zone-action: #252019;
  --zone-divider: rgba(208, 160, 107, 0.22);
  --workspace-card-surface-dark:
    radial-gradient(circle at top right, color-mix(in srgb, var(--accent) 10%, transparent), transparent 36%),
    linear-gradient(180deg, var(--zone-chrome), color-mix(in srgb, var(--zone-chrome) 88%, var(--zone-reading) 12%));
  --workspace-card-surface: var(--workspace-card-surface-dark);
  --zone-chrome-cream: var(--zone-chrome);
  --zone-reading-cream: var(--zone-reading);
  --toolbar-header-bg: var(--workspace-card-surface);
  --toolbar-header-bg-solid: var(--zone-chrome);
  --toolbar-header-border: var(--zone-divider);
  --toolbar-control-bg: var(--zone-elevated);
  --toolbar-control-hover-bg: color-mix(in srgb, var(--zone-elevated) 80%, var(--accent) 20%);
  --toolbar-control-active-bg: var(--accent);
  --toolbar-control-active-fg: #1a1208;
  --toolbar-control-border: rgba(245, 242, 234, 0.14);
  --toolbar-control-fg: #f7ebdf;
  --toolbar-control-muted-bg: rgba(255, 255, 255, 0.06);
  --mushaf-reading-surface: var(--zone-chrome);
  --mushaf-reading-ink: #f7ebdf;
  --ayah-mark-ink: #f0e6d4;
}

html[data-theme="sepia"] body.memorisation-page {
  --zone-canvas: var(--bg);
  --zone-reading-cream: var(--surface-strong);
  --zone-chrome-cream: var(--bg);
  --zone-reading: var(--zone-reading-cream);
  --zone-chrome: var(--bg);
  --zone-panel: var(--bg);
  --zone-elevated: var(--surface-strong);
  --zone-action: color-mix(in srgb, var(--bg) 92%, var(--accent) 8%);
  --zone-divider: var(--border);
  --workspace-card-surface:
    radial-gradient(circle at top right, color-mix(in srgb, var(--accent) 10%, transparent), transparent 34%),
    linear-gradient(165deg, color-mix(in srgb, var(--zone-chrome) 90%, white 10%), var(--zone-chrome));
  --toolbar-header-bg: var(--workspace-card-surface);
  --toolbar-header-bg-solid: var(--zone-chrome);
  --toolbar-header-border: var(--zone-divider);
  --toolbar-control-bg: var(--surface-strong);
  --toolbar-control-hover-bg: color-mix(in srgb, var(--zone-chrome) 70%, var(--surface-strong));
  --toolbar-control-active-bg: var(--text);
  --toolbar-control-active-fg: var(--surface-strong);
  --toolbar-control-border: color-mix(in srgb, var(--text) 10%, transparent);
  --toolbar-control-fg: var(--text);
  --toolbar-control-muted-bg: color-mix(in srgb, var(--surface-strong) 72%, transparent);
  --mushaf-reading-surface: var(--surface-strong);
  --mushaf-reading-ink: var(--text);
  --ayah-mark-ink: var(--text);
}

html[data-theme="sepia"] body.memorisation-page .tools-top {
