  --verse-font-percent: 100;
  --verse-font-size: clamp(1.1rem, calc(var(--verse-font-percent, 100) * 0.01rem), 1.6rem);
  font-family: var(--quran-font, var(--font-ar));
  /* If we scale UI, apply it to Arabic too. */
  font-size: calc(var(--verse-font-size) * var(--ui-scale, 1) * var(--text-scale, 1));
  line-height: 1.7;
  text-align: right;
  direction: rtl;
  unicode-bidi: isolate;
  background: transparent;
  padding: 8px 8px 4px;
  border-radius: 16px;
  margin: 6px 0 4px;
  display: block;
  /* anywhere fractures Arabic joining / shows stray tatweel dashes */
  overflow-wrap: normal;
  word-break: keep-all;
  line-break: strict;
}

.verse-arabic .verse-ayah-end-number,
.verse-arabic-with-end .verse-ayah-end-number {
  /* Pre-rendered ornate marker PNG — digit already centered in the asset */
  position: relative;
  display: inline-block !important;
  white-space: nowrap !important;
  box-sizing: content-box;
  vertical-align: -0.42em;
  width: 1.45em;
  height: 1.55em;
  margin-inline: 0.14em 0.08em;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none;
  color: var(--ayah-mark-ink) !important;
  line-height: 0;
  font-size: 1em;
  opacity: 1 !important;
  visibility: visible !important;
  overflow: hidden !important;
  transform: translateY(0.12em);
  float: none !important;
  z-index: 2;
}
