  width: 1.55em;
  height: 1.55em;
}
.verse-arabic .verse-ayah-number-digits-3.verse-ayah-end-number {
  width: 1.7em;
  height: 1.55em;
}
.verse-arabic .verse-ayah-end-number__img,
.verse-arabic-with-end .verse-ayah-end-number__img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  object-fit: contain;
  object-position: center center;
  pointer-events: none;
  user-select: none;
  border: 0;
  margin: 0;
  padding: 0;
  position: absolute;
  inset: 0;
}
.verse-arabic .verse-ayah-end-number__digit,
.verse-arabic-with-end .verse-ayah-end-number__digit {
