/* Idle card — entrance & micro-interactions */
@keyframes workspace-idle-enter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes workspace-idle-ring-in {
  from {
    opacity: 0;
    transform: scale(0.9);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes workspace-idle-progress-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.workspace-shell.is-idle-card {
  animation: workspace-idle-enter 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.workspace-shell-idle-ring {
  animation: workspace-idle-ring-in 560ms cubic-bezier(0.22, 1, 0.36, 1) 120ms both;
}

.workspace-shell-idle--continuing .workspace-shell-idle-aside {
  animation: workspace-idle-progress-in 440ms cubic-bezier(0.22, 1, 0.36, 1) 180ms both;
}

.workspace-shell-idle-quickstart .workspace-shell-idle-choice:nth-child(1) {
  animation: workspace-idle-enter 440ms cubic-bezier(0.22, 1, 0.36, 1) 100ms both;
}

.workspace-shell-idle-quickstart .workspace-shell-idle-choice:nth-child(2) {
  animation: workspace-idle-enter 440ms cubic-bezier(0.22, 1, 0.36, 1) 160ms both;
}

.workspace-shell-idle-actions__start,
.workspace-shell-idle-aside-cta {
  animation: workspace-idle-enter 440ms cubic-bezier(0.22, 1, 0.36, 1) 200ms both;
}

.workspace-shell-idle-links {
  animation: workspace-idle-enter 440ms cubic-bezier(0.22, 1, 0.36, 1) 260ms both;
}

@media (prefers-reduced-motion: reduce) {
  .workspace-shell.is-idle-card,
  .workspace-shell-idle-ring,
  .workspace-shell-idle--continuing .workspace-shell-idle-aside,
  .workspace-shell-idle-quickstart .workspace-shell-idle-choice,
  .workspace-shell-idle-actions__start,
  .workspace-shell-idle-aside-cta,
  .workspace-shell-idle-links {
    animation: none;
  }

  .workspace-shell-idle-choice,
  .workspace-shell-idle .session-idle-action,
