  flex: 0 0 auto;
  font-size: 0.95rem;
  color: #fff;
  background: linear-gradient(180deg, #a56f3d, #8f5d31);
  box-shadow: 0 4px 10px rgba(139, 94, 60, 0.22);
}

.playback-pill-ring {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--text-muted) 55%, transparent);
  flex: 0 0 auto;
}

.playback-pill-ring.is-playing {
  background: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
}

.playback-pill-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.1rem;
  min-width: 0;
  text-align: start;
}

.playback-pill-copy strong,
.playback-pill-copy small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playback-pill-copy strong {
  font-size: 0.86rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: var(--text);
}

.playback-pill-copy small {
  color: color-mix(in srgb, var(--text) 62%, var(--text-muted));
  font-size: 0.7rem;
  font-weight: 500;
}

@media (max-width: 768px) {
  .player-dock.tools-open {
    left: 50%;
    transform: translateX(-50%);
    width: min(100%, calc(100vw - 16px));
    bottom: calc(env(safe-area-inset-bottom, 0px) + 10px);
  }

  .tools.open,
.tools.show {
    z-index: 1100;
  }
}

.player-dock > * {
  pointer-events: auto;
}

.player-dock:has(.player-bar.is-playing) .player-dock-card {
  border-color: color-mix(in srgb, var(--mq-player-glass-border) 78%, var(--accent));
  box-shadow:
    0 1.5px 0 rgba(255, 255, 255, 0.88) inset,
    0 -0.5px 0 rgba(255, 255, 255, 0.24) inset,
    0 16px 44px rgba(28, 20, 12, 0.18),
    0 6px 16px rgba(28, 20, 12, 0.1);
}

[data-theme="dark"] .player-dock:has(.player-bar.is-playing) .player-dock-card {
  border-color: rgba(255, 255, 255, 0.42);
  box-shadow:
    0 1.5px 0 rgba(255, 255, 255, 0.28) inset,
    0 -0.5px 0 rgba(255, 255, 255, 0.08) inset,
    0 18px 46px rgba(0, 0, 0, 0.44),
    0 6px 16px rgba(0, 0, 0, 0.24);
}

.player-bar {
  position: relative;
  width: 100%;
  background: linear-gradient(180deg, rgba(255, 253, 249, 0.98), rgba(250, 244, 235, 0.96));
  border: 1px solid rgba(120, 78, 40, 0.22);
  border-radius: 18px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 4px 12px rgba(29, 17, 7, 0.06),
    0 16px 36px rgba(29, 17, 7, 0.11);
  padding: 14px 18px 15px;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.28s ease, box-shadow 0.28s ease, border-color 0.28s ease, padding 0.28s ease;
  will-change: transform, opacity;
}

.player-accent {
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 4%,
    color-mix(in srgb, var(--accent) 28%, transparent) 28%,
    color-mix(in srgb, var(--accent) 72%, transparent) 50%,
    color-mix(in srgb, var(--accent) 28%, transparent) 72%,
    transparent 96%
  );
  opacity: 0.55;
  pointer-events: none;
}

.player-bar.is-playing {
  border-color: rgba(120, 78, 40, 0.3);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.75) inset,
    0 6px 14px rgba(29, 17, 7, 0.07),
    0 18px 40px rgba(29, 17, 7, 0.13);
}

.player-bar.is-playing .player-accent {
  opacity: 0.95;
}

.player-bar.compact {
  padding: 10px 14px 11px;
}

.player-main {
  display: grid;
  grid-template-columns: minmax(150px, 1.1fr) auto minmax(260px, 2fr) auto;
  align-items: center;
  gap: clamp(10px, 1.5vw, 18px);
  min-width: 0;
  position: relative;
  z-index: 1;
}

.player-info {
  min-width: 0;
  padding-inline-start: 2px;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.player-chapter {
  font-weight: 650;
  font-size: 0.92rem;
  letter-spacing: -0.015em;
  line-height: 1.25;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.player-verse {
  font-size: 0.76rem;
  font-weight: 500;
  line-height: 1.3;
  color: color-mix(in srgb, var(--text) 64%, var(--text-muted, #6b5a48));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.player-eta {
  color: var(--accent);
  font-weight: 600;
  opacity: 1;
}

.player-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}

.player-btn {
  width: 38px;
  height: 38px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  color: color-mix(in srgb, var(--text) 88%, var(--text-muted));
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.05rem;
  transition: background 0.16s ease, transform 0.16s ease, border-color 0.16s ease, color 0.16s ease, box-shadow 0.16s ease;
  flex: 0 0 auto;
}

.player-btn:hover {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--accent) 14%, transparent);
  color: var(--text);
}

.player-btn:active {
  transform: scale(0.96);
}

.player-btn:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 55%, transparent);
  outline-offset: 2px;
}

.player-play {
  position: relative;
  background: linear-gradient(180deg, #a97442, #8f5d31);
  color: #fff;
  width: 48px;
  height: 48px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, #fff 18%, transparent);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.22) inset,
    0 6px 14px rgba(139, 94, 60, 0.24);
}

.player-play > .bi {
  position: relative;
  z-index: 1;
  font-size: 1.2rem;
  margin-inline-start: 1px;
}

.player-play > .bi.bi-pause-fill {
  margin-inline-start: 0;
}

.player-play-ring {
  position: absolute;
  inset: -3px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, transparent);
  opacity: 0;
  transform: scale(0.96);
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
}

.player-bar.is-playing .player-play-ring {
  opacity: 0.85;
  transform: scale(1);
  animation: playerRingPulse 2.8s ease-in-out infinite;
}

.player-play:hover {
  background: linear-gradient(180deg, #b57f4c, #9a6738);
  color: #fff;
  transform: scale(1.03);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.26) inset,
    0 8px 16px rgba(139, 94, 60, 0.28);
}

.player-play:active {
  transform: scale(0.98);
}

.player-close,
.player-layout-toggle {
  width: 34px;
  height: 34px;
  background: transparent;
  color: color-mix(in srgb, var(--text) 58%, var(--text-muted));
  font-size: 0.92rem;
}

.player-close:hover,
.player-layout-toggle:hover {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border-color: transparent;
  color: var(--text);
}

.player-mini {
  display: flex;
  align-items: center;
  gap: clamp(8px, 1.2vw, 12px);
  min-width: 0;
  position: relative;
  z-index: 1;
}

.player-mini-info {
  flex: 1;
  min-width: 0;
  text-align: start;
  padding: 1px 0;
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  color: inherit;
  cursor: default;
}

.player-mini .player-play {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
}

.player-mini .player-play > .bi {
  font-size: 1.1rem;
}

.player-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
}

.player-progress-wrap {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.player-time {
  font-size: 0.7rem;
  font-weight: 550;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: color-mix(in srgb, var(--text) 55%, var(--text-muted));
  min-width: 2.5rem;
  line-height: 1;
}

.player-time.elapsed {
  text-align: end;
}

.player-time.total {
  text-align: start;
}

.player-progress-bg {
  flex: 1;
  height: 4px;
  background: color-mix(in srgb, var(--text) 10%, transparent);
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  border: none;
  overflow: visible;
  transition: height 0.16s ease;
}

.player-progress-bg:hover,
.player-progress-bg:focus-visible {
  height: 6px;
}

.player-progress-bg:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 45%, transparent);
  outline-offset: 4px;
}

.player-progress-fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: linear-gradient(90deg, #8f5d31, #b88852);
  border-radius: 999px;
  transition: width 0.12s linear;
}

.player-progress-thumb {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid #9a6738;
  box-shadow: 0 1px 4px rgba(88, 59, 29, 0.2);
  transform: translateY(-50%) scale(0.86);
  opacity: 0.92;
  pointer-events: none;
  transition: left 0.12s linear, transform 0.16s ease, opacity 0.16s ease;
}

.player-progress-bg:hover .player-progress-thumb,
.player-bar.is-playing .player-progress-thumb {
  transform: translateY(-50%) scale(1);
  opacity: 1;
}

@keyframes playerRingPulse {
  0%,
100% {
    opacity: 0.45;
    transform: scale(1);
  }

  50% {
    opacity: 0.85;
    transform: scale(1.03);
  }
}

@keyframes playerDockBreathe {
  0%,
100% {
    transform: translateX(-50%) translateY(0);
  }

  50% {
    transform: translateX(-50%) translateY(-2px);
  }
}

@media (max-width: 900px) {
  .player-main {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "info actions"
      "controls controls"
      "progress progress";
    gap: 10px;
  }

  .player-info {
    grid-area: info;
  }

  .player-controls {
    grid-area: controls;
    justify-content: center;
  }

  .player-progress-wrap {
    grid-area: progress;
  }

  .player-actions {
    grid-area: actions;
    justify-self: end;
  }

  .player-mini {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto auto;
    align-items: center;
  }
}

.slide-up-enter-active {
  transition: transform 0.42s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.34s ease;
}

.slide-up-leave-active {
  transition: transform 0.28s cubic-bezier(0.4, 0, 1, 1), opacity 0.22s ease;
}

.slide-up-enter-from,
.slide-up-leave-to {
  transform: translate(-50%, 28px) scale(0.985);
  opacity: 0;
}

.verse-translation {
  font-size: calc(1.2rem * var(--en-scale, 1));
  color: #1c1917;
  line-height: 1.65;
  display: block;
  opacity: 1;
  font-family: 'Outfit', sans-serif;
  direction: ltr;
  text-align: left;
  unicode-bidi: isolate;
  margin-top: 0.65rem;
  padding-top: 0.35rem;
}

.verse-aid-block {
  margin-top: 10px;
  direction: ltr;
  text-align: left;
}

.verse-aid-source {
  margin: 0.28rem 0 0;
  font-size: 0.84rem;
  font-weight: 500;
  line-height: 1.35;
  color: var(--text-muted, #64748b);
}

.verse-transliteration {
  font-size: calc(0.98rem * var(--en-scale, 1));
  color: #1c1917;
  font-style: italic;
  line-height: 1.5;
  opacity: 1;
  font-family: 'Outfit', sans-serif;
  direction: ltr;
  text-align: left;
  unicode-bidi: isolate;
  margin-top: 0.65rem;
  padding-top: 0.35rem;
}

.verse-words {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  direction: rtl;
  margin-top: 12px;
  padding-top: 10px;
