  overflow-x: hidden;
  overflow-x: clip;
  overflow-y: hidden;
  padding-bottom: 8px;
}

.word-item {
  position: relative;
  background: var(--accent-light);
  padding: 6px 12px;
  border-radius: 20px;
  display: inline-flex;
  flex-direction: row-reverse;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  flex: 0 0 auto;
