}

.quiz-title-wrap {
  display: grid;
  gap: 4px;
}

.quiz-title {
  font-weight: 600;
  font-size: 1.05rem;
}

.quiz-title-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.quiz-x {
