  font-size: 0.74rem;
  color: var(--text-muted);
  line-height: 1.45;
}

.quiz-summary-mistakes {
  display: grid;
  gap: 8px;
}

.quiz-summary-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.quiz-tag {
  padding: 8px 10px;
  border-radius: 999px;
  background: rgba(190, 73, 73, 0.10);
  border: 1px solid rgba(190, 73, 73, 0.18);
  color: rgba(140, 30, 30, 0.9);
  font-weight: 500;
  font-size: 0.72rem;
}

.quiz-prompt {
  font-size: 1.02rem;
  color: var(--text);
  line-height: 1.7;
}

.quiz-section-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  color: var(--text-muted);
  font-weight: 500;
