  gap: 8px;
  padding: 8px 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--border) 88%, #cbb79a);
  background: #fffaf3;
  color: var(--text);
  box-shadow: var(--shadow-lg);
  font-weight: 450;
  animation: riseSoft 220ms ease-out;
  backdrop-filter: none;
}

.banner.success {
  border-color: #8fbf9f;
  background: #e7f4ec;
}

.banner.info {
  border-color: #d2b898;
  background: #f4eadc;
}

.banner.warning {
  border-color: #e0c08a;
  background: #f8efd9;
}

.banner.error {
  border-color: #e0a3a3;
  background: #f8e4e4;
}

.banner.important {
  z-index: 1065;
  box-shadow: 0 18px 40px rgba(20, 12, 4, 0.18);
  border-width: 2px;
}

.banner.persistent {
  top: calc(72px + env(safe-area-inset-top, 0px));
}

