body.memorisation-page {
  --bg-body: #f7f3ef;
  --surface-elevated: #fffbf7;

  --text-primary: #231f1c;
  --text-secondary: #5a5048;
  --text-muted: #5a5048;
  --accent-deep: #8b532b;
  --warning: #9a6207;
  --warning-strong: #7a4d05;
  --warning-soft: rgba(154, 98, 7, 0.14);
  --error: #a94438;
  --error-strong: #8f382e;
  --error-soft: rgba(169, 68, 56, 0.14);
  --border-light: rgba(78, 58, 38, 0.18);
  --border-medium: rgba(78, 58, 38, 0.28);
  --radius-card: 20px;
  --radius-element: 14px;
  --transition: all 0.2s ease;
}

.verse-card {
  background: var(--surface);
  border-radius: var(--radius-card);
  padding: 28px;
  margin-bottom: 20px;
  border: 1px solid var(--border-light);
  transition: var(--transition);
}

.verse-card.active {
  border-left: 4px solid var(--accent);
  box-shadow: var(--shadow-md);
}

.verse-arabic {
  font-family: var(--quran-font, var(--font-ar, 'UthmanicHafs', 'Amiri', 'Noto Naskh Arabic', serif));
  font-size: 2.2rem;
  line-height: 1.8;
  text-align: right;
  direction: rtl;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.verse-translation {
  color: var(--text-secondary);
  font-size: calc(1.2rem * var(--en-scale, 1));
  line-height: 1.65;
}

.toggle-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  border-radius: 40px;
  background: var(--surface);
  border: 1px solid var(--border-medium);
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-chip.active {
  background: var(--accent);
  border-color: var(--accent);
  color: white;
}

.progress-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 10px;
  transition: width 0.3s ease;
}

.btn-primary {
