/* ----------------------------------------------------------------------------
   Responsive layer (breakpoint-free).
   Replaces the former max-width media queries: layout now adapts purely through
   intrinsic CSS — auto-fit grids,
flex-wrap and fluid clamp() sizing — so the
   top card,
ayah cards and the mushaf scale from phone to desktop without any
   viewport breakpoints.
   ---------------------------------------------------------------------------- */

/* Button / control clusters wrap instead of overflowing on narrow screens. */
.completion-header,
.session-overview-card,
.session-overview-top,
.session-overview-controls,
.session-overview-actions,
.completion-actions,
.action-buttons-row,
.action-buttons-group,
.reading-toolbar-controls,
.toolbar-dropdown-row,
.font-theme-border-row {
  flex-wrap: wrap;
}

/* Fixed-count grids collapse automatically as the available width shrinks. */
.completion-actions-inline {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
}

.recitation-result-actions,
.self-check-result-group,
.self-check-review-actions {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 9.5rem), 1fr));
}

.recitation-result-stats {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10.25rem), 1fr));
}

.recitation-insights-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13.75rem), 1fr));
}

/* Mushaf page padding scales down on small viewports without a breakpoint. */
.mushaf-page {
  padding: clamp(1.1rem, 4vw, 4.5rem) clamp(0.85rem, 6vw, 5.25rem) clamp(1rem, 3vw, 3rem);
}

/* Keep the top session card in a two-track grid instead of stacking. */
.workspace-shell {
  overflow: visible !important;
  z-index: 12000;
}

.workspace-shell-head {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(8.75rem, min(54vw, 34rem));
  align-items: start !important;
  column-gap: clamp(0.4rem, 1.6vw, 0.85rem);
  row-gap: 0.5rem;
  min-width: 0;
}

.workspace-shell-copy {
  min-width: 0;
}

.workspace-shell-main-title,
.workspace-shell-copy h1 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: normal;
}

.workspace-shell-actions {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start !important;
  justify-content: stretch !important;
  gap: clamp(0.3rem, 1.3vw, 0.55rem) !important;
  min-width: 0;
  width: 100%;
}

.workspace-header-view-controls,
.quick-right-controls {
  display: grid !important;
  grid-template-columns: minmax(4.8rem, 1fr) minmax(3.2rem, 0.72fr);
  align-items: center !important;
  justify-content: stretch !important;
  gap: clamp(0.25rem, 1vw, 0.5rem) !important;
  min-width: 0;
  width: 100%;
}

.view-mode-switch,
.quick-font-dropdown .font-dropdown-trigger,
.workspace-shell-actions .action-btn,
.workspace-shell-actions .top-card-ellipsis {
  min-width: 0 !important;
}

.workspace-header-view-controls .view-mode-switch {
  width: 100%;
  padding-inline: clamp(0.35rem, 1.4vw, 0.55rem) !important;
  gap: clamp(0.28rem, 1vw, 0.5rem) !important;
}

.view-mode-switch-label,
.workspace-header-view-controls .font-dropdown-trigger span,
.mushaf-toolbar-trigger-label,
.mushaf-pill-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.view-mode-switch-label {
  max-width: clamp(2.1rem, 9vw, 4.4rem);
}

.workspace-header-view-controls .font-dropdown-trigger {
  width: 100%;
  padding-inline: clamp(0.35rem, 1.4vw, 0.72rem);
}

.workspace-shell-actions .action-buttons-group {
