  display: none;
}

.workspace-shell-actions {
  flex: 0 1 auto;
  min-width: min(100%, 18rem);
  width: auto;
  display: flex !important;
  flex-wrap: wrap;
  justify-content: flex-end !important;
  align-items: center !important;
  gap: 8px !important;
}

.workspace-header-view-controls,
.quick-right-controls {
  width: min(100%, 34rem);
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(10.5rem, auto);
  align-items: stretch !important;
  justify-content: stretch !important;
  gap: 8px !important;
}

.workspace-header-view-controls .view-mode-switch {
  width: 100%;
  min-width: 0 !important;
  justify-content: space-between;
  padding-inline: 0.8rem !important;
  gap: 0.65rem !important;
}

.workspace-header-view-controls .font-dropdown-trigger {
  width: 100%;
  min-width: 0;
  justify-content: space-between;
  padding-inline: 0.8rem;
}

.workspace-shell-actions .action-buttons-group {
  width: 100%;
  display: flex !important;
  flex-wrap: wrap !important;
  justify-content: flex-end !important;
  gap: 8px;
}

.workspace-shell-actions .action-btn,
.workspace-shell-actions .top-card-ellipsis {
  width: auto !important;
  min-width: 44px !important;
  height: 44px;
  padding-inline: 0.9rem !important;
}

.workspace-shell-actions .action-btn[aria-label="Open session controls"],
.workspace-shell-actions .top-card-ellipsis {
  width: 44px !important;
  padding-inline: 0 !important;
}

.workspace-shell-actions .top-card-session-actions:not(.post-session-choice-pair) .action-btn.primary,
.workspace-shell-actions .top-card-session-actions:not(.post-session-choice-pair) .action-btn.btn-primary,
.workspace-shell-actions .top-card-session-actions:not(.post-session-choice-pair) .session-primary-action,
.workspace-shell-actions .top-card-session-actions:not(.post-session-choice-pair) .action-btn-exit {
  min-width: max-content !important;
  width: auto !important;
  padding-inline: 0.65rem !important;
}

/* Post-session pair: content-sized on desktop; mobile media query forces equal columns. */
.workspace-shell-actions .post-session-choice-pair > .session-primary-action,
.workspace-shell-actions .post-session-choice-pair > .action-btn-exit,
.workspace-shell-actions .post-session-choice-pair > .post-session-choice-custom,
.workspace-shell-actions .post-session-choice-pair > .top-card-action-trigger {
  min-width: max-content !important;
  width: auto !important;
  max-width: none !important;
  padding-inline: 0.9rem !important;
}

@media (max-width: 767.98px) {
  .workspace-shell-actions .post-session-choice-pair > .session-primary-action,
.workspace-shell-actions .post-session-choice-pair > .action-btn-exit,
.workspace-shell-actions .post-session-choice-pair > .post-session-choice-custom,
.workspace-shell-actions .post-session-choice-pair > .top-card-action-trigger {
    min-width: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    padding-inline: 0.4rem !important;
  }
}

.workspace-shell-actions .action-btn.primary span,
.workspace-shell-actions .action-btn.btn-primary span,
.workspace-shell-actions .session-primary-action span,
.workspace-shell-actions .workspace-ai-recite-cta span,
.workspace-shell-actions .action-btn-exit span,
.workspace-shell-actions .post-session-choice-custom span,
.workspace-shell-actions .post-session-choice-return span {
  display: inline;
}

.workspace-shell-actions .action-btn.primary i,
.workspace-shell-actions .action-btn-exit i {
  margin: 0;
}

.workspace-quick-controls {
  display: none;
}

.top-card-menu {
  width: min(19rem, calc(100vw - 28px));
  max-width: min(19rem, calc(100vw - 28px));
  padding: 8px;
}

.top-card-menu button,
.verse-action-menu button {
  min-height: 44px;
  justify-content: flex-start !important;
  text-align: left;
  padding-inline: 12px;
}

.top-card-menu button span,
.verse-action-menu button span,
.quick-font-dropdown .font-dropdown-trigger span,
.workspace-header-view-controls .font-dropdown-trigger span,
.view-mode-switch-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

