}

.mushaf-pill-toolbar .mushaf-pill {
  width: auto;
  min-width: 44px !important;
  padding-inline: 0.85rem;
}

.mushaf-pill-toolbar .mushaf-controls-pill {
  padding-inline: 0 !important;
