  --mutqin-modal-backdrop-blur: 10px;
  --mutqin-modal-surface-border: color-mix(in srgb, var(--border) 62%, var(--accent) 38%);
  --mutqin-modal-surface-bg:
    radial-gradient(90% 70% at 8% -10%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 52%),
    radial-gradient(70% 50% at 100% 0%, color-mix(in srgb, #2f6f58 8%, transparent), transparent 46%),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--zone-elevated, var(--surface)) 98%, #fff 2%),
      color-mix(in srgb, var(--zone-reading, var(--surface)) 90%, var(--zone-elevated, var(--surface)) 10%)
    );
  --mutqin-modal-surface-solid: color-mix(in srgb, var(--surface-elevated, var(--surface)) 98%, transparent);
  --mutqin-modal-hero-bg: color-mix(in srgb, var(--accent-wash, var(--accent-light, var(--accent))) 55%, var(--surface-elevated, var(--surface)));
  --mutqin-modal-shadow:
    0 1px 0 color-mix(in srgb, #fff 62%, transparent) inset,
    0 22px 48px color-mix(in srgb, #0f1110 14%, transparent),
    0 48px 100px color-mix(in srgb, #0f1110 18%, transparent);
  --mutqin-modal-enter-duration: 480ms;
  --mutqin-modal-enter-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --mutqin-modal-btn-radius: 12px;
