  --ps-mint-border: rgba(47, 111, 88, 0.28);
  position: fixed;
  inset: 0;
  z-index: 14000;
  pointer-events: none;
}

.post-session-simple__backdrop {
  position: fixed;
  inset: 0;
  pointer-events: auto;
  background: var(--mutqin-modal-backdrop);
  backdrop-filter: blur(var(--mutqin-modal-backdrop-blur)) saturate(1.15);
  -webkit-backdrop-filter: blur(var(--mutqin-modal-backdrop-blur)) saturate(1.15);
  animation: mutqinBackdropFade 280ms ease;
}

[data-theme="light"] .post-session-simple__backdrop {
  background: var(--mutqin-modal-backdrop);
}

.post-session-simple__overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(1.25rem, env(safe-area-inset-top, 0px)) 1.25rem max(1.25rem, env(safe-area-inset-bottom, 0px));
  box-sizing: border-box;
  overflow: auto;
}

.post-session-simple__dialog {
  pointer-events: auto;
  width: min(52rem, calc(100vw - 2rem));
  max-width: min(52rem, calc(100vw - 2rem));
  max-height: 90vh;
  margin: auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: var(--mutqin-modal-radius);
  border: 1px solid color-mix(in srgb, var(--border) 72%, transparent);
  background: var(--mutqin-modal-surface-bg);
  box-shadow:
    0 1px 0 color-mix(in srgb, #fff 55%, transparent) inset,
    0 24px 64px color-mix(in srgb, #14231c 16%, transparent);
  overflow: hidden;
  position: relative;
  animation: mutqinModalEnter var(--mutqin-modal-enter-duration) var(--mutqin-modal-enter-ease) both;
}

body > .viewport-confetti,
body > .viewport-confetti-canvas,
.post-session-simple > .viewport-confetti {
  position: fixed !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  min-height: 100dvh !important;
  overflow: visible !important;
  border-radius: 0 !important;
  pointer-events: none !important;
