.post-session-simple__header {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1.15rem 1.45rem 0.95rem;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 48%, transparent);
  background: var(--mutqin-modal-hero-bg);
  min-width: 0;
}

.post-session-simple__check {
  flex-shrink: 0;
  width: 2.35rem;
  height: 2.35rem;
  display: grid;
  place-items: center;
  margin-top: 0.02rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--ps-mint) 26%, transparent);
