[data-theme="dark"] .action-btn.primary,
[data-theme="dark"] .action-btn.btn-primary,
[data-theme="dark"] .action-btn-primary,
[data-theme="dark"] .session-primary-action.btn-primary,
[data-theme="dark"] .session-resume-btn.btn-primary,
[data-theme="dark"] .self-check-action-btn.btn-primary,
