/* Post-session optional checks — unified matched rows */
.post-session-simple__review {
  display: grid;
  gap: 0.65rem;
  min-width: 0;
  width: 100%;
}

.post-session-simple__review-head {
  display: grid;
  gap: 0.2rem;
}

.post-session-simple__review-lead {
  margin: 0;
  padding-inline-start: 1.65rem;
  font-size: 0.8rem;
  line-height: 1.4;
  font-weight: 400;
  color: color-mix(in srgb, var(--text) 58%, transparent);
}

/* Post-session flow — clear steps + readable explanations */
.post-session-simple__stack--flow.ps-flow {
  display: grid;
  gap: 1.15rem;
}

.ps-flow__intro {
  margin: 0;
  padding: 0.85rem 1rem;
  border-radius: 0.95rem;
  border: 1px solid color-mix(in srgb, var(--ps-mint, #2f6f58) 16%, var(--border));
  background: color-mix(in srgb, var(--ps-mint, #2f6f58) 7%, #fff);
  font-size: 0.9rem;
  line-height: 1.5;
  color: color-mix(in srgb, var(--text) 78%, transparent);
}

.ps-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.85rem 1rem;
  align-items: start;
}

.ps-step__rail {
  display: grid;
  justify-items: center;
  gap: 0.45rem;
  padding-top: 0.15rem;
}

.ps-step__num {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ps-mint, #2f6f58) 12%, #fff);
  border: 1px solid color-mix(in srgb, var(--ps-mint, #2f6f58) 22%, var(--border));
  color: var(--ps-mint, #2f6f58);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.ps-step__num--plan {
  background: var(--ps-mint, #2f6f58);
  border-color: transparent;
  color: #fff;
  box-shadow: 0 8px 16px color-mix(in srgb, var(--ps-mint, #2f6f58) 22%, transparent);
}

.ps-step__line {
  width: 2px;
  min-height: 2.5rem;
  flex: 1 1 auto;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ps-mint, #2f6f58) 18%, var(--border));
  align-self: stretch;
}

.ps-step__content {
  display: grid;
  gap: 0.7rem;
  min-width: 0;
}

.ps-step__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.ps-step__titles {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.ps-step__eyebrow {
  margin: 0;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: color-mix(in srgb, var(--text) 52%, transparent);
}

.ps-step__dot {
  margin-inline: 0.2rem;
  opacity: 0.55;
}

.ps-quiz,
.ps-plan {
  --ps-accent: var(--ps-mint, #2f6f58);
  padding: 1.1rem 1.15rem 1.15rem;
  border-radius: 1.2rem;
  border: 1px solid color-mix(in srgb, var(--border) 72%, transparent);
  background: color-mix(in srgb, var(--surface) 98%, #fff);
  animation: ps-rise 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.ps-quiz {
  border-color: color-mix(in srgb, var(--ps-accent) 14%, var(--border));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--ps-accent) 5%, #fff) 0%, color-mix(in srgb, var(--surface) 98%, #fff) 38%);
}

.ps-quiz--done {
  border-color: color-mix(in srgb, var(--ps-accent) 22%, var(--border));
}

.ps-plan {
  border-color: color-mix(in srgb, var(--ps-accent) 22%, var(--border));
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--ps-accent) 9%, #fff) 0%, color-mix(in srgb, var(--surface) 98%, #fff) 46%);
  box-shadow:
    0 1px 0 color-mix(in srgb, #fff 60%, transparent) inset,
    0 14px 32px color-mix(in srgb, var(--ps-accent) 8%, transparent);
  animation-delay: 50ms;
}

.ps-quiz__brand {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  min-height: 1.55rem;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ps-accent) 10%, #fff);
  border: 1px solid color-mix(in srgb, var(--ps-accent) 16%, var(--border));
  color: var(--ps-accent);
  font-size: 0.7rem;
  font-weight: 650;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.ps-quiz__title,
.ps-plan__title {
  margin: 0;
  color: var(--text);
}

.ps-quiz__title {
  font-size: clamp(1.05rem, 2.4vw, 1.2rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.3;
}

.ps-quiz__sub {
  margin: 0;
  font-size: 0.92rem;
  line-height: 1.55;
  color: color-mix(in srgb, var(--text) 78%, transparent);
}

.ps-quiz__why {
  margin: 0;
  padding: 0.7rem 0.85rem;
  border-radius: 0.85rem;
  border-inline-start: 3px solid color-mix(in srgb, var(--ps-accent) 55%, transparent);
  background: color-mix(in srgb, var(--ps-accent) 6%, #fff);
  font-size: 0.86rem;
  line-height: 1.5;
  color: color-mix(in srgb, var(--text) 72%, transparent);
