  background: color-mix(in srgb, var(--border) 32%, transparent);
}

.memory-check-choice.is-selected .memory-check-choice-mark {
  background: color-mix(in srgb, #2f6f58 16%, transparent);
  color: #2f6f58;
}

.memory-check-choice-text {
  font-size: 0.98rem;
  line-height: 1.55;
}

.memory-check-order {
  display: grid;
  gap: 0.4rem;
}

.memory-check-order-hint {
