/* Shared workspace flow contract.
 * The progress rail, session header, and either reading surface are sibling
 * rows. Keeping their spacing in one grid prevents Mushaf/card-specific drift
 * when the rail wraps or the navbar changes height.
 */
.workspace {
  --workspace-flow-gap: clamp(0.65rem, 1.35vw, 1rem);
  --workspace-progress-rail-h: clamp(42px, 3.2vw, 46px);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  row-gap: var(--workspace-flow-gap);
  align-content: start;
}

.session-progress-rail {
  grid-column: 1;
  top: var(--navbar-height, var(--navbar-offset, 64px));
  margin: 0;
  min-height: var(--workspace-progress-rail-h);
  isolation: isolate;
}

.session-progress-rail__inner {
  min-height: var(--workspace-progress-rail-h);
  box-sizing: border-box;
  background: var(--bg);
}

.workspace-shell,
.workspace-main {
  grid-column: 1;
  scroll-margin-block-start: calc(
    var(--navbar-height, var(--navbar-offset, 64px))
    + var(--workspace-progress-rail-h)
    + var(--workspace-flow-gap)
  );
}

.workspace-shell {
  margin-block: 0;
}

