/* Workspace spotlight tour — dim everything except the active target */
.workspace-tour {
  position: fixed;
  inset: 0;
  z-index: 32000;
  pointer-events: auto;
}

.workspace-tour__blocker {
  position: fixed;
  background: transparent;
  pointer-events: auto;
}

.workspace-tour__hole {
  position: fixed;
  border: 0;
  outline: 0;
  border-radius: var(--tour-hole-radius, 16px);
  box-shadow: 0 0 0 9999px color-mix(in srgb, #0a100d 62%, transparent);
  pointer-events: auto;
  transition: opacity 160ms ease, border-radius 160ms ease;
  z-index: 32001;
}

.workspace-tour__dashboard {
  position: fixed;
  inset: 4.5rem 0.75rem 0.75rem;
  z-index: 32000;
  pointer-events: none;
  border-radius: 16px;
  overflow: hidden;
  background: var(--surface, #fffaf3);
  box-shadow: 0 16px 48px color-mix(in srgb, #14231c 22%, transparent);
}

.tools-tabs.is-tour-clickable {
  pointer-events: none;
}

.workspace-tour__dashboard-preview {
  position: absolute;
  inset: 0;
  overflow: auto;
  padding: 0;
  display: block;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent, #c48a4a) 8%, #fffaf3) 0%, var(--bg, #f6f3ee) 7.5rem);
  color: var(--text, #1f1a17);
  pointer-events: none;
}

.workspace-tour__dashboard-shell.container-fluid.user-dashboard__shell {
  --dash-gutter: clamp(0.85rem, 3.2vw, 1.25rem);
  width: 100%;
  max-width: 100%;
  padding: 0.85rem var(--dash-gutter) 1.2rem;
  margin-inline: 0;
  display: grid;
  gap: 0.85rem;
  align-content: start;
  box-sizing: border-box;
}

.workspace-tour__dash-skeleton {
  display: grid;
  gap: 0.65rem;
}

.workspace-tour__dash-skel {
  display: block;
  border-radius: 10px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--border, #e7e0d8) 55%, transparent) 0%,
    color-mix(in srgb, var(--surface, #fff) 90%, #fff) 45%,
    color-mix(in srgb, var(--border, #e7e0d8) 55%, transparent) 100%
