  background-size: 200% 100%;
  animation: workspace-tour-dash-shimmer 1.15s ease-in-out infinite;
}

.workspace-tour__dash-skel--title {
  height: 1.35rem;
  width: min(72%, 16rem);
}

.workspace-tour__dash-skel--chip {
