/* AI Memorisation Detection — mushaf hidden-text surface + practice HUD */

.amd-overlay {
  position: fixed;
  inset: 0;
  z-index: 30000 !important;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto !important;
}

.amd-overlay .mutqin-modal-dialog,
.amd-overlay .amd-modal,
.amd-overlay .amd-modal button,
.amd-overlay .amd-tool,
.amd-overlay .amd-actions,
.amd-overlay .btn-primary,
.amd-overlay .btn-secondary {
  pointer-events: auto !important;
}

.amd-overlay .mutqin-modal-dialog,
.amd-overlay .amd-modal {
  position: relative;
  z-index: 1;
}

.amd-modal {
  max-width: min(920px, calc(100vw - 2rem));
  width: min(920px, calc(100vw - 2rem));
  max-height: min(94vh, 980px);
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #f7f4ef 0%, #fbfaf7 36%, #ffffff 100%);
  color: #1c1917;
  box-shadow: 0 24px 60px rgba(28, 25, 23, 0.18);
}

.amd-modal--mushaf .amd-body {
  overflow: auto;
  flex: 1;
}

.amd-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.15rem 1.35rem 0.65rem;
  border-bottom: 1px solid rgba(68, 64, 60, 0.08);
}

.amd-header-aside {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  flex-shrink: 0;
}

.amd-mic-status--header {
  margin: 0;
}

.amd-kicker {
  margin: 0 0 0.2rem;
  color: #78716c;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.amd-header-copy h2 {
  margin: 0;
  font-size: 1.28rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: #1c1917;
}

.amd-range {
  margin: 0.3rem 0 0;
  color: #57534e;
  font-size: 0.95rem;
}

.amd-range--title {
  margin: 0;
  font-size: 1.28rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: #1c1917;
}

.amd-body {
  padding: 0.75rem 1.35rem 1.35rem;
}

.amd-panel {
  display: grid;
  gap: 1rem;
}

.amd-lead {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.55;
  color: #292524;
  max-width: 42rem;
}

.amd-howto {
  margin: 0;
  padding: 0.85rem 0.85rem 0.85rem 1.4rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(68, 64, 60, 0.08);
  color: #44403c;
  display: grid;
  gap: 0.45rem;
  line-height: 1.45;
}

.amd-meta {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.amd-meta li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.7rem 0.9rem;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(68, 64, 60, 0.08);
}

.amd-meta span { color: #57534e; font-size: 0.9rem; }
.amd-meta strong { color: #1c1917; font-weight: 600; }
.amd-meta strong[data-status="denied"],
.amd-meta strong[data-status="unsupported"] {
  color: #9a3412;
  text-decoration: underline dashed;
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.12em;
}

.amd-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.amd-actions .btn-primary,
.amd-actions .btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.amd-error {
  margin: 0;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  background: #fff7ed;
  color: #9a3412;
  border: 1px solid rgba(154, 52, 18, 0.36);
  border-style: solid;
}

/* Tools */
.amd-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.amd-tool {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid rgba(68, 64, 60, 0.14);
  background: rgba(255, 255, 255, 0.85);
  color: #44403c;
  border-radius: 999px;
  padding: 0.45rem 0.75rem;
  font-size: 0.86rem;
  cursor: pointer;
}

.amd-tool:hover:not(:disabled) {
  background: #fff;
  border-color: rgba(68, 64, 60, 0.28);
}

.amd-tool.active,
.amd-tool.recording {
  background: rgba(22, 163, 74, 0.12);
  border-color: rgba(22, 163, 74, 0.35);
  color: #166534;
}

.amd-tool.recording {
  background: rgba(185, 28, 28, 0.1);
  border-color: rgba(185, 28, 28, 0.28);
  color: #991b1b;
}

.amd-tool:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.amd-live-banner {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1rem 1.15rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid rgba(68, 64, 60, 0.08);
}

.amd-live-banner--recording {
  background: color-mix(in srgb, #dc2626 8%, #fff);
  border: 1px solid color-mix(in srgb, #dc2626 28%, transparent);
  box-shadow: 0 8px 22px rgba(185, 28, 28, 0.08);
}

.amd-live-banner--recording .amd-live-dot {
  background: #dc2626;
  box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.45);
  animation: amd-pulse 1.4s ease-out infinite;
}

.amd-live-banner--recording strong {
  color: #991b1b;
  font-size: 0.98rem;
  letter-spacing: 0.01em;
}

.amd-live-banner--recording p {
  color: #7f1d1d;
}

.amd-live-banner--recording .amd-timer {
  color: #991b1b;
  font-size: 1.05rem;
}

.amd-live-banner__copy {
  min-width: 0;
  flex: 1 1 auto;
}

.amd-live-banner strong { display: block; color: #1c1917; }
.amd-live-banner p { margin: 0.2rem 0 0; color: #57534e; font-size: 0.92rem; line-height: 1.4; }
.amd-timer {
  margin-inline-start: auto;
  font-variant-numeric: tabular-nums;
  font-weight: 650;
  color: #166534;
}

.amd-live-dot,
.amd-rec-dot {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 999px;
  background: #16a34a;
  flex-shrink: 0;
  box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.45);
  animation: amd-pulse 1.8s ease-out infinite;
}

.amd-live-banner[data-stage="processing"] .amd-live-dot,
.amd-live-banner[data-stage="analysing"] .amd-live-dot,
.amd-live-banner[data-stage="starting"] .amd-live-dot {
  background: #ca8a04;
}

@keyframes amd-pulse {
  0% { box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.4); }
  70% { box-shadow: 0 0 0 12px rgba(22, 163, 74, 0); }
  100% { box-shadow: 0 0 0 0 rgba(22, 163, 74, 0); }
}

/* Mushaf shell */
.amd-mushaf-shell {
  position: relative;
  padding: 1.1rem 1rem 1.25rem;
  border-radius: 16px;
  background: #fff;
  border: 1px solid rgba(68, 64, 60, 0.1);
  min-height: 220px;
}

.amd-mushaf-ayah {
  font-size: clamp(1.35rem, 3.2vw, 1.85rem);
  line-height: 2.15;
  color: #111827;
}

.amd-ayah-block {
  display: flex;
  flex-direction: row-reverse;
  align-items: flex-start;
  gap: 0.65rem;
  margin-bottom: 0.85rem;
}

.amd-ayah-marker {
  flex-shrink: 0;
  width: 1.7rem;
  height: 1.7rem;
  margin-top: 0.35rem;
  border-radius: 999px;
  border: 1px solid rgba(68, 64, 60, 0.25);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  color: #57534e;
  background: #fafaf9;
}

.amd-ayah-words {
  flex: 1;
  text-align: right;
}

.amd-mushaf-ayah .wbw-word,
.amd-mushaf-ayah word {
  display: inline;
  padding: 0.05rem 0.12rem;
  border-radius: 0.35rem;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.amd-mushaf-ayah .recitation-word-correct {
  color: #15803d;
  background: transparent;
}

.amd-mushaf-ayah .recitation-word-partial {
  color: #b45309;
  background: transparent;
}

.amd-mushaf-ayah .recitation-word-incorrect {
  color: #b91c1c;
  background: transparent;
}

.amd-mushaf-ayah .recitation-word-omitted {
  color: #111827;
  background: transparent;
}

/* Inserted non-Qur'an words have no Mushaf glyph; mark the nearest anchor. */
.amd-mushaf-ayah .amd-word-insertion-anchor {
  border-bottom: 2px dotted #b91c1c;
}

/* Hidden words keep their original inline box — never display:none / collapse. */
.amd-mushaf-ayah .amd-word-hidden,
.amd-mushaf-shell.is-hidden-text .recitation-word-notAttempted,
.amd-mushaf-shell.is-hidden-text .recitation-word-pending {
  display: inline !important;
  visibility: visible;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  background: color-mix(in srgb, #a8a29e 22%, transparent) !important;
  border-bottom: none;
  border-radius: 0.28em;
  text-shadow: none !important;
  box-shadow: inset 0 -0.12em 0 color-mix(in srgb, #a8a29e 45%, transparent);
  filter: none !important;
  opacity: 1 !important;
  font-size: inherit !important;
  letter-spacing: inherit !important;
  word-spacing: inherit !important;
  line-height: inherit !important;
  padding: 0.04rem 0.12rem;
  margin: 0;
  user-select: none !important;
  -webkit-user-select: none !important;
  -webkit-touch-callout: none;
  pointer-events: none;
  caret-color: transparent;
  transition: background-color 180ms ease, box-shadow 180ms ease, color 180ms ease;
}

.amd-mushaf-ayah .amd-word-hidden::selection,
.amd-mushaf-shell.is-hidden-text .recitation-word-notAttempted::selection,
.amd-mushaf-shell.is-hidden-text .recitation-word-pending::selection {
  background: transparent !important;
  color: transparent !important;
}

/* Soft blur is opt-in only — default gap mask must not reflow or float glyphs. */
.amd-mushaf-shell.is-blur-active .amd-word-hidden {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: blur(6px) !important;
}

/* Gap mask: stable-width hidden slots without leaking Arabic via soft blur. */
.amd-mushaf-shell.is-gap-mask .amd-word-hidden {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  filter: none !important;
  background: color-mix(in srgb, #a8a29e 22%, transparent) !important;
  border-radius: 0.28em;
  box-shadow: inset 0 -0.12em 0 color-mix(in srgb, #a8a29e 45%, transparent);
}

.amd-mushaf-ayah .amd-word-revealed {
  filter: none;
  color: inherit;
  animation: amd-word-reveal 200ms ease;
}

.amd-mushaf-ayah .amd-word-current {
  box-shadow: none;
  border-radius: 0.25em;
}

.amd-mushaf-ayah:not(.tajweed-enabled) .amd-word-current {
  background: color-mix(in srgb, #b08a4a 14%, transparent);
}

.amd-mushaf-shell.is-peeking .amd-word-peeked {
  color: #44403c !important;
  -webkit-text-fill-color: #44403c !important;
  filter: none;
  background: transparent !important;
  outline: none !important;
  box-shadow: none !important;
  text-decoration: none !important;
  pointer-events: none;
  user-select: none;
}

.amd-tool--peek.active {
  background: color-mix(in srgb, #b08a4a 16%, #fff);
  border-color: color-mix(in srgb, #b08a4a 42%, transparent);
  color: #6b5429;
}

@keyframes amd-word-reveal {
  from { opacity: 0.35; filter: blur(4px); }
  to { opacity: 1; filter: none; }
}

@media (prefers-reduced-motion: reduce) {
  .amd-mushaf-ayah .amd-word-revealed,
  .amd-mushaf-ayah .amd-word-hidden {
    transition: none;
    animation: none;
  }
}

.amd-title {
  margin: 0;
  font-family: "Iowan Old Style", "Palatino Linotype", Palatino, "Source Serif 4", "Noto Serif", Georgia, serif;
  font-size: clamp(1.2rem, 3vw, 1.35rem);
  font-weight: 650;
  letter-spacing: -0.02em;
  color: #1c1917;
}

.amd-header--compact {
  padding-bottom: 0.5rem;
}

.amd-modal--test {
  max-width: min(1120px, calc(100vw - 1.25rem));
  width: min(1120px, calc(100vw - 1.25rem));
  max-height: min(94vh, 1040px);
}

.amd-mic-status {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.15rem 0 0.65rem;
  padding: 0.45rem 0.9rem;
  min-height: 2.15rem;
  border-radius: 999px;
  background: color-mix(in srgb, #f5f5f4 88%, #fff);
  color: #57534e;
  font-size: 0.86rem;
  font-weight: 600;
  border: 1px solid transparent;
}

.amd-mic-status[data-status="listening"],
.amd-mic-status--recording {
  color: #991b1b;
  background: color-mix(in srgb, #dc2626 12%, #fff);
  border-color: color-mix(in srgb, #dc2626 32%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, #dc2626 10%, transparent);
}

.amd-mic-status--starting {
  color: #92400e;
  background: color-mix(in srgb, #f59e0b 14%, #fff);
  border-color: color-mix(in srgb, #d97706 28%, transparent);
}

.amd-mic-status--reconnecting {
  color: #92400e;
  background: color-mix(in srgb, #f59e0b 16%, #fff);
  border-color: color-mix(in srgb, #d97706 34%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, #f59e0b 12%, transparent);
}

.amd-mic-status[data-status="need_access"],
.amd-mic-status[data-status="unsupported"] {
  color: #9a3412;
  background: color-mix(in srgb, #ea580c 10%, #fff);
}

.amd-mic-dot {
  display: none !important;
}

.amd-mic-status[data-status="listening"] .amd-mic-dot,
.amd-mic-status--recording .amd-mic-dot {
  background: #dc2626;
  box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.45);
  animation: amd-mic-pulse 1.2s ease infinite;
}

.amd-mic-status--starting .amd-mic-dot {
  background: #d97706;
  animation: amd-mic-pulse 1.6s ease infinite;
}

.amd-mic-status--reconnecting .amd-mic-dot {
  display: inline-block !important;
  background: #d97706;
  animation: amd-mic-pulse 1s ease infinite;
}

@keyframes amd-mic-pulse {
  70% { box-shadow: 0 0 0 10px rgba(220, 38, 38, 0); }
  100% { box-shadow: 0 0 0 0 rgba(220, 38, 38, 0); }
}

.amd-help-wrap {
  position: relative;
}

.amd-help-popover {
  position: absolute;
  top: calc(100% + 0.4rem);
  inset-inline-start: 0;
  z-index: 5;
  width: min(18rem, 70vw);
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  background: #fff;
  border: 1px solid rgba(68, 64, 60, 0.12);
  box-shadow: 0 12px 28px rgba(28, 25, 23, 0.12);
  color: #44403c;
  font-size: 0.88rem;
  line-height: 1.45;
}

.amd-help-popover p {
  margin: 0;
}

.amd-help-mic {
  margin-top: 0.45rem !important;
  color: #78716c;
  font-size: 0.82rem;
}

.amd-difficulty {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-inline-start: auto;
}

.amd-difficulty__label {
  font-size: 0.78rem;
  color: #78716c;
}

.amd-difficulty__select {
  min-height: 2.5rem;
  min-width: 4.5rem;
  padding: 0.35rem 0.55rem;
  border-radius: 10px;
  border: 1px solid rgba(68, 64, 60, 0.16);
  background: #fff;
  color: #1c1917;
  font-size: 0.88rem;
}

.amd-tool {
  min-height: 44px;
  min-width: 44px;
}

.amd-tool--peek.active {
  background: color-mix(in srgb, #b08a4a 14%, #fff);
  border-color: color-mix(in srgb, #b08a4a 35%, transparent);
}

.amd-complete {
  margin-top: 0.85rem;
  padding: 1rem 1.1rem;
  border-radius: 14px;
  background: color-mix(in srgb, #2f6f58 8%, #fff);
  border: 1px solid color-mix(in srgb, #2f6f58 18%, transparent);
  text-align: center;
}

.amd-complete__title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 600;
  color: #1c1917;
}

.amd-complete__body {
  margin: 0.35rem 0 0;
  color: #57534e;
  font-size: 0.92rem;
}

.amd-complete__actions {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-top: 0.9rem;
}

.amd-inline-error {
  margin-top: 0.75rem;
  padding: 0.85rem 1rem;
  border-radius: 12px;
  background: color-mix(in srgb, #ea580c 8%, #fff);
  border: 1px solid color-mix(in srgb, #ea580c 20%, transparent);
  color: #9a3412;
  display: grid;
  gap: 0.65rem;
  justify-items: start;
}

.amd-ayah-empty {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-content: center;
  gap: 0.35rem;
  padding: 1.25rem;
  text-align: center;
  pointer-events: none;
  background: color-mix(in srgb, var(--surface, #fff) 88%, transparent);
  color: var(--text-muted, #6b6560);
}

.amd-ayah-empty strong {
  color: var(--text, #1f1812);
  font-size: 0.95rem;
}

.amd-ayah-empty p {
  margin: 0;
  max-width: 22rem;
  font-size: 0.86rem;
  line-height: 1.45;
}

[data-theme="dark"] .amd-ayah-empty {
  background: color-mix(in srgb, var(--surface, #1c1916) 90%, transparent);
}

[data-theme="dark"] .amd-ayah-empty strong {
  color: var(--text, #f3eee7);
}

.amd-inline-error p {
  margin: 0;
  font-size: 0.9rem;
}

.amd-inline-error__steps {
  margin: 0;
  padding-inline-start: 1.15rem;
  font-size: 0.88rem;
  line-height: 1.45;
}

.amd-footer-mic-strip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem 0.75rem;
  width: 100%;
  margin-bottom: 0.65rem;
  padding: 0.55rem 0.65rem;
  border-radius: 0.75rem;
  border: 1px solid color-mix(in srgb, currentColor 10%, transparent);
  background: color-mix(in srgb, var(--surface, #fff) 92%, transparent);
}

.amd-footer-mic-strip__status {
  grid-column: 1 / -1;
}

.amd-footer-mic-level {
  position: relative;
  height: 0.35rem;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, currentColor 12%, transparent);
  grid-column: 1;
}

.amd-footer-mic-level__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2e9d62, #b77a45);
  transition: width 80ms linear;
}

.amd-footer-mic-retry {
  grid-column: 2;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.86rem;
  font-weight: 650;
  text-decoration: underline;
  text-underline-offset: 0.14em;
  cursor: pointer;
  white-space: nowrap;
}

.amd-mic-status[data-status="checking"],
.amd-mic-status[data-status="low_input"],
.amd-mic-status[data-status="no_device"],
.amd-mic-status[data-status="recording_issue"] {
  border-color: color-mix(in srgb, #ea580c 28%, transparent);
  background: color-mix(in srgb, #ea580c 10%, transparent);
}

.amd-mushaf-shell {
  min-height: min(52vh, 520px);
  max-height: min(62vh, 640px);
  overflow: auto;
  padding: 1.25rem 1.1rem 1.5rem;
  border-radius: 16px;
  background: #fff;
  border: 1px solid rgba(68, 64, 60, 0.08);
}

.amd-ayah-block.is-active {
  scroll-margin: 2rem;
}

@media (max-width: 768px) {
  .amd-overlay {
    align-items: stretch;
  }

  .amd-dialog,
  .amd-modal--test {
    width: 100%;
    max-width: 100%;
    max-height: 100%;
    height: 100%;
    border-radius: 0;
    margin: 0;
  }

  .amd-modal--test {
    display: flex;
    flex-direction: column;
  }

  .amd-header--compact {
    position: sticky;
    top: 0;
    z-index: 2;
    background: linear-gradient(180deg, #f7f4ef 0%, #fbfaf7 100%);
  }

  .amd-body--mushaf {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
  }

  .amd-toolbar {
    flex-wrap: nowrap;
    align-items: center;
  }

  .amd-difficulty {
    width: auto;
    margin-inline-start: auto;
    flex: 0 0 auto;
    justify-content: flex-end;
  }

  .amd-mushaf-shell {
    flex: 1;
    min-height: 0;
    max-height: none;
  }

  .amd-tool span {
    display: inline;
  }
}

.amd-mushaf-ayah .amd-word-frequent {
  box-shadow: inset 0 -3px 0 rgba(185, 28, 28, 0.55);
}

.amd-bottom-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 0.25rem;
