}
.amd-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
}
.amd-stats article {
  padding: 0.75rem;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.78);
