}
.amd-ayah-card p { margin: 0; color: #57534e; font-size: 0.9rem; }

.amd-plan-card {
  display: grid;
  gap: 0.85rem;
  padding: 1.1rem;
  border-radius: 16px;
  background: #fff;
  border: 1px solid rgba(68, 64, 60, 0.1);
}
.amd-plan-kicker {
  color: #78716c;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.amd-plan-card h3 {
  margin: 0.25rem 0 0;
  font-size: 1.2rem;
  color: #1c1917;
}
.amd-plan-why { margin: 0; color: #44403c; line-height: 1.5; }
.amd-plan-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}
.amd-plan-grid div,
.amd-weak-words,
.amd-techniques article {
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
  background: #fafaf9;
}
.amd-plan-grid span,
.amd-weak-words > span {
  display: block;
  color: #78716c;
  font-size: 0.8rem;
  margin-bottom: 0.2rem;
}
.amd-weak-words em {
  font-style: normal;
  margin-inline-start: 0.35rem;
  color: #9a3412;
}
.amd-techniques { display: grid; gap: 0.55rem; }
.amd-techniques strong { display: block; margin-bottom: 0.2rem; }
.amd-techniques p { margin: 0; color: #57534e; font-size: 0.92rem; }

.amd-adjust {
  display: grid;
  gap: 0.75rem;
  padding: 0.9rem;
  border-radius: 12px;
  background: #fafaf9;
}
.amd-adjust label {
  display: grid;
  gap: 0.35rem;
  color: #44403c;
  font-size: 0.92rem;
}
.amd-adjust input[type="number"],
.amd-adjust select {
  border: 1px solid rgba(68, 64, 60, 0.18);
  border-radius: 10px;
  padding: 0.55rem 0.7rem;
  background: #fff;
  color: #1c1917;
}
.amd-checkbox {
  display: flex !important;
  align-items: center;
  gap: 0.5rem;
}

.amd-practice-hud {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  background: linear-gradient(180deg, #f7f4ef 0%, #fff 100%);
