/* Live feedback names the difference between a recogniser pause and a settled
 * recitation issue without covering the mushaf or demanding a response. */
.amd-live-feedback {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  min-height: 3.25rem;
  margin: 0.65rem 0 0;
  padding: 0.55rem 0.7rem;
  border: 1px solid color-mix(in srgb, #386b9e 22%, transparent);
  border-radius: 0.7rem;
  background: color-mix(in srgb, #edf5ff 72%, var(--mutqin-modal-surface-bg, #fff));
  color: #254a70;
}

.amd-live-feedback > i {
  flex: 0 0 auto;
  margin-top: 0.08rem;
  font-size: 1rem;
}

.amd-live-feedback span {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
}

.amd-live-feedback strong,
.amd-live-feedback small {
  line-height: 1.28;
}

.amd-live-feedback strong {
  font-size: 0.78rem;
  font-weight: 720;
}

.amd-live-feedback small {
  color: inherit;
  font-size: 0.71rem;
  opacity: 0.82;
}

.amd-live-feedback.is-checking {
  border-color: color-mix(in srgb, #a5660c 28%, transparent);
  background: color-mix(in srgb, #fff4dd 76%, var(--mutqin-modal-surface-bg, #fff));
  color: #88520b;
}

.amd-live-feedback.is-confirmed {
  border-color: color-mix(in srgb, #a13a32 30%, transparent);
  background: color-mix(in srgb, #fff0ed 78%, var(--mutqin-modal-surface-bg, #fff));
  color: #8f3029;
}

/* Cool dotted underline means the recogniser is still deciding, never a red
 * recitation error. It remains deliberately quieter than a final mismatch. */
.amd-mushaf-ayah--premium .recitation-word-uncertain,
.amd-mushaf-stream .recitation-word-uncertain {
  color: #4d728c !important;
  -webkit-text-fill-color: #4d728c !important;
