/*
 * Canonical phone composition.
 *
 * The legacy stylesheet contains the desktop design and historical responsive
 * rules. This final layer owns every layout below 768px and places related UI
 * on an explicit four-column grid rather than flattening it into full-width rows.
 */
@media (max-width: 767.98px) {
  .app {
    --mq-mobile-gutter: clamp(16px, 4.8vw, 22px);
    --mq-grid-gap: clamp(6px, 1.8vw, 10px);
    --mq-grid: repeat(4, minmax(0, 1fr));
    --mq-card-pad: clamp(12px, 3.6vw, 16px);
    --mq-control-size: 44px;
    --mq-top-icon: var(--mq-control-size);
    --mq-radius-card: 18px;
    --mq-radius-compact: 14px;
    --mq-safe-top: env(safe-area-inset-top, 0px);
    --mq-safe-right: env(safe-area-inset-right, 0px);
    --mq-safe-bottom: env(safe-area-inset-bottom, 0px);
    --mq-safe-left: env(safe-area-inset-left, 0px);
    --mobile-page-gutter: var(--mq-mobile-gutter);
    --mobile-safe-top: var(--mq-safe-top);
    --mobile-safe-bottom: var(--mq-safe-bottom);
    --mq-mushaf-inline-start: max(0px, var(--mq-safe-left));
    --mq-mushaf-inline-end: max(0px, var(--mq-safe-right));
    inline-size: 100%;
    max-inline-size: 100%;
  }

  .app,
.app *,
.app *::before,
.app *::after {
    box-sizing: border-box;
  }

  .workspace-main,
  .verses-grid,
  .mushaf-viewport,
  .mushaf-page {
    max-width: 100%;
    overflow-x: clip;
    overflow-y: visible;
  }

  .main.mushaf-mode-active .mushaf-viewport,
  .main.mushaf-mode-active .mushaf-viewport-scroll,
  .main.mushaf-mode-active .mushaf-page,
  .main.mushaf-mode-active .mushaf-page--madani,
  .main.mushaf-mode-active .mushaf-page-body {
    overflow-x: visible !important;
    max-width: 100% !important;
  }

  .main.madani-qpc-mode-active .workspace-main,
  .main.madani-qpc-mode-active .madani-qpc-workspace,
  .main.madani-qpc-mode-active .madani-qpc-viewport,
  .main.madani-qpc-mode-active .madani-qpc-stage,
  .main.madani-qpc-mode-active .madani-qpc-stage__pages {
    max-width: 100% !important;
    min-width: 0 !important;
    overflow-x: clip !important;
    overflow-y: visible !important;
  }

  .app :where(
    .main,
    .content,
    .workspace,
    .workspace-main,
    .session-progress-rail,
    .workspace-shell,
    .workspace-shell-head,
    .workspace-shell-copy,
    .workspace-shell-actions,
    .workspace-shell-bottom,
    .workspace-shell-metadata,
    .workspace-shell-idle,
    .workspace-shell-idle-inner,
    .workspace-shell-idle-main,
    .workspace-shell-idle-aside,
    .workspace-shell-idle-actions,
    .workspace-shell-idle-links,
    .verses-grid,
    .verse-card,
    .verse-header,
    .verse-badges,
    .verse-statuses,
    .verse-actions,
    .verse-arabic,
    .tools,
    .tools-top,
    .tools-body,
    .tools-footer,
    .sheet,
    .sheet-section,
    .sheet-content,
    .field-stack,
    .field,
    .setting-row,
    .player-dock,
    .player-bar,
    .player-main,
    .mutqin-modal-dialog,
    .mutqin-modal-surface,
    .self-check-modal-body,
    .self-check-modal-stage,
    .shared-result-flow,
    .shared-result-section,
    .recordings-library-shell,
    .recordings-library-nav,
    .recordings-library-detail
  ) {
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  .main {
    inline-size: 100%;
    padding-inline: var(--mq-mobile-gutter) !important;
  }

  .content,
.workspace,
.workspace-main {
    inline-size: 100%;
    margin-inline: 0 !important;
    padding-inline: 0 !important;
  }

  .practice-technique-status {
    margin-block: 0 8px;
    padding-inline: 0;
    gap: 6px;
  }

  .practice-technique-status__item {
    min-height: 26px;
    padding: 3px 8px;
    font-size: 0.72rem;
  }

  /* Workspace overview: title/utilities, actions, and metadata share one grid. */
  .workspace-shell,
.main.mushaf-mode-active .workspace-shell {
    display: grid !important;
    grid-template-columns: var(--mq-grid);
    gap: 12px var(--mq-grid-gap) !important;
    inline-size: 100% !important;
    margin: 0 0 14px !important;
    padding: var(--mq-card-pad) !important;
    min-block-size: 0 !important;
    border-radius: 20px;
  }

  .workspace-shell-head:not(.is-idle) {
    grid-column: 1 / -1;
    display: grid !important;
    grid-template-columns: var(--mq-grid) !important;
    gap: 10px var(--mq-grid-gap) !important;
    align-items: center !important;
  }

  .workspace-shell-head.is-idle {
    grid-column: 1 / -1;
    display: block !important;
    grid-template-columns: none !important;
    grid-template-rows: none !important;
    align-items: stretch !important;
    padding-block: 0 !important;
  }

  .workspace-shell-copy {
    grid-column: 1;
    grid-row: 1;
    min-width: 0;
    display: grid;
    gap: 3px;
    align-self: center;
  }

  .workspace-shell-kicker {
    inline-size: max-content;
    max-inline-size: 100%;
  }

  .workspace-shell-idle .workspace-shell-main-title,
  .workspace-shell-idle .workspace-shell-copy h1 {
    display: flex !important;
    flex-wrap: nowrap !important;
    align-items: baseline !important;
    gap: 0.45rem !important;
    min-width: 0 !important;
    max-width: 100% !important;
    white-space: nowrap !important;
    overflow: visible !important;
    overflow-wrap: normal !important;
    line-height: 1.45 !important;
    padding-block: 0.08rem 0.2rem !important;
  }

  .workspace-shell-idle .workspace-shell-idle-title-en,
  .workspace-shell-idle .workspace-shell-idle-title-ar {
    display: inline !important;
    flex: 0 1 auto !important;
    min-width: 0 !important;
    white-space: nowrap !important;
    overflow: visible !important;
    text-overflow: clip !important;
    line-height: 1.45 !important;
  }

  .workspace-shell-idle .workspace-shell-idle-title-ar {
    line-height: 1.5 !important;
    padding-block: 0.06em 0.1em !important;
  }

  .workspace-shell-idle--fresh .workspace-shell-main-title,
  .workspace-shell-idle--fresh .workspace-shell-copy h1 {
    font-family: var(--font-surah-latin) !important;
    font-size: clamp(1.02rem, 0.9rem + 1.8vw, 1.22rem) !important;
    font-weight: 700 !important;
    letter-spacing: 0.01em !important;
    line-height: 1.45 !important;
    color: var(--text) !important;
  }

  .workspace-shell-idle--continuing .workspace-shell-main-title,
  .workspace-shell-idle--continuing .workspace-shell-copy h1 {
    font-family: var(--font-surah-latin) !important;
    font-size: clamp(1.05rem, 0.92rem + 2vw, 1.28rem) !important;
    line-height: 1.45 !important;
    font-weight: 700 !important;
    letter-spacing: 0.015em !important;
    color: color-mix(in srgb, var(--text) 82%, var(--accent) 18%) !important;
  }

  .workspace-shell-idle--fresh .workspace-shell-kicker {
    padding: 0.2rem 0.55rem !important;
    background: color-mix(in srgb, var(--accent-light, var(--surface)) 55%, transparent) !important;
    border-radius: 999px !important;
    font-size: 0.625rem !important;
  }

  .workspace-shell-idle--continuing .workspace-shell-kicker {
    padding: 0 !important;
    background: none !important;
    font-size: 0.625rem !important;
  }

  .workspace-shell-idle,
  .workspace-shell-idle-inner,
  .workspace-shell-idle-main,
  .workspace-shell-idle-aside,
  .workspace-shell-idle-actions,
  .workspace-shell-idle-links,
  .workspace-shell-lead {
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  .workspace-shell-idle-inner {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    justify-content: space-between !important;
    inline-size: 100% !important;
    gap: 0.75rem !important;
  }

  .workspace-shell-idle--fresh .workspace-shell-idle-inner {
    flex-direction: column !important;
    align-items: stretch !important;
  }

  .workspace-shell-idle-main {
    flex: 1 1 auto !important;
    min-inline-size: 0 !important;
    gap: 0.75rem !important;
  }

  .workspace-shell-idle-aside {
    flex: 0 0 auto !important;
    margin-inline-start: auto !important;
    gap: 0.3rem !important;
    padding-inline-start: 0 !important;
    border-inline-start: 0 !important;
  }

  .workspace-shell-idle-aside-cta {
    display: none !important;
