    min-block-size: 2.35rem !important;
    justify-content: center !important;
    padding-inline: 1rem !important;
    font-size: 0.875rem !important;
  }

  .workspace-shell-idle-watermark {
    display: none !important;
  }

  .workspace-shell-idle-ring {
    inline-size: 3.75rem !important;
    block-size: 3.75rem !important;
    width: 3.75rem !important;
    height: 3.75rem !important;
  }

  .workspace-shell-idle-ring__label {
    max-inline-size: 5rem !important;
    font-size: 0.5875rem !important;
  }

  .workspace-shell-idle-note {
    font-size: clamp(0.78rem, 2.6vw, 0.8125rem) !important;
    line-height: 1.45 !important;
  }

  .workspace-shell-idle-chips {
    flex-wrap: wrap !important;
    gap: 0.35rem !important;
  }

  .workspace-shell-idle-actions {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 0.5rem !important;
    inline-size: 100% !important;
  }

  .workspace-shell-idle-quickstart {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 0.55rem !important;
    inline-size: 100% !important;
  }

  .workspace-shell-idle-choice {
    inline-size: 100% !important;
    min-block-size: 0 !important;
    padding: 0.68rem 0.8rem !important;
  }

@media (min-width: 768px) {
  .workspace-shell-idle-aside-cta {
    display: block !important;
  }

  .workspace-shell-idle-actions__start--inline {
    display: none !important;
  }
}

  .workspace-shell-idle .workspace-shell-main-title::after {
    display: none !important;
    content: none !important;
  }

  .workspace-shell-idle-links {
    display: inline-flex !important;
    flex-wrap: wrap !important;
    gap: 0.35rem !important;
    justify-content: flex-start !important;
  }

  .workspace-shell-idle .workspace-shell-main-title {
    overflow: visible !important;
    text-overflow: clip !important;
    white-space: normal !important;
  }

  .workspace-shell-head:not(.is-idle) .workspace-shell-main-title,
  .workspace-shell-head:not(.is-idle) .workspace-shell-copy h1 {
    margin: 0;
    padding-inline: 0.05rem;
    padding-block: 0.08rem 0.32rem;
    font-family: "Iowan Old Style", "Palatino Linotype", Palatino, "Source Serif 4", "Noto Serif", Georgia, serif !important;
    font-size: clamp(1.05rem, 0.92rem + 2.2vw, 1.32rem) !important;
    line-height: 1.45 !important;
    font-weight: 700 !important;
    letter-spacing: 0.015em !important;
    color: color-mix(in srgb, var(--text) 78%, var(--accent) 22%) !important;
    white-space: normal !important;
    overflow: visible !important;
    overflow-wrap: normal !important;
  }

  .workspace-shell-head:not(.is-idle) .workspace-shell-surah-en {
    font-family: "Iowan Old Style", "Palatino Linotype", Palatino, "Source Serif 4", "Noto Serif", Georgia, serif !important;
    font-weight: 700 !important;
    letter-spacing: 0.015em !important;
    line-height: 1.45 !important;
    overflow: visible !important;
  }

  .workspace-shell-head:not(.is-idle) .workspace-shell-surah-ar {
    font-family: var(--font-surah-arabic, "Amiri", "Noto Naskh Arabic", "Scheherazade New", serif) !important;
    font-weight: 700 !important;
    line-height: 1.5 !important;
    overflow: visible !important;
  }

  .workspace-shell-lead {
    max-inline-size: 100% !important;
    font-size: clamp(0.78rem, 2.8vw, 0.875rem) !important;
  }

  .workspace-shell-lead,
  .workspace-shell-text-link {
    overflow-wrap: anywhere;
  }

  /* Compact session progress pills under Surah title (mobile only) — own grid row */
  .workspace-shell-progress-pills {
    grid-column: 1 / -1 !important;
    grid-row: 2 !important;
    display: flex !important;
    flex-flow: row wrap !important;
    align-items: center;
    gap: 0.35rem;
    width: 100% !important;
    inline-size: 100% !important;
    max-inline-size: 100%;
    min-inline-size: 0;
    margin: 0;
    padding: 0.55rem 0;
    overflow-x: hidden;
    overflow-x: clip;
    overflow-y: hidden;
  }

  .workspace-shell-progress-pills::-webkit-scrollbar {
    display: none;
  }

  .workspace-shell-progress-pill {
    display: inline-flex !important;
    align-items: center;
    flex: 0 0 auto;
    max-inline-size: 8.5rem;
    min-inline-size: 0;
    margin: 0;
    padding: 0.14rem 0.48rem;
    border: 1px solid color-mix(in srgb, var(--border) 85%, transparent);
    border-radius: 999px;
    background: color-mix(in srgb, var(--surface) 92%, var(--bg));
    color: color-mix(in srgb, var(--text) 72%, transparent);
    font-size: 0.64rem;
    font-weight: 600;
    line-height: 1.15;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    pointer-events: none;
    user-select: none;
  }

  [data-theme="dark"] .workspace-shell-progress-pill {
    border-color: color-mix(in srgb, var(--border) 90%, transparent);
    background: color-mix(in srgb, var(--surface) 88%, #1a1613);
    color: color-mix(in srgb, var(--text) 78%, transparent);
  }

  /* Session CTAs sit on their own row below the pills (not shared with row 2) */
