    grid-column: 1 / -1;
    grid-row: 3;
    display: grid !important;
    grid-template-columns: var(--mq-grid) !important;
    gap: 10px var(--mq-grid-gap) !important;
    inline-size: 100% !important;
    pointer-events: auto;
