  .workspace-shell-actions .top-card-session-actions.has-paired-actions:not(.post-session-choice-pair) {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    flex: none !important;
    gap: 0.35rem !important;
    width: 100% !important;
    min-width: 0 !important;
  }

  .workspace-shell-actions .top-card-session-actions.post-session-choice-pair,
.workspace-shell-actions .top-card-session-actions.has-paired-actions.post-session-choice-pair,
.workspace-shell--post-session-choice .post-session-choice-pair,
.workspace-shell--post-session-choice .post-session-choice-pair.has-paired-actions {
