/* Homepage — light / sepia / dark via shared tokens */
@import url('https://fonts.bunny.net/css?family=source-serif-4:400,500,600,700');

.homepage {
  --hp-display: "Source Serif 4", "Iowan Old Style", Palatino, "Amiri", "Noto Naskh Arabic", Georgia, serif;
  --hp-text: "Nunito", "Avenir Next", "Segoe UI", "Noto Naskh Arabic", system-ui, sans-serif;
  --section-y: clamp(2.4rem, 5.5vw, 4.2rem);

  --hp-muted: color-mix(in srgb, var(--text-muted) 88%, var(--text));
  --hp-heading: color-mix(in srgb, var(--text) 96%, var(--text-on-accent));
  --hp-glow: color-mix(in srgb, var(--accent) 14%, transparent);
  --hp-border: color-mix(in srgb, var(--accent) 12%, var(--border));
  --hp-focus: color-mix(in srgb, var(--accent) 20%, transparent);
  --shot-radius: 1.1rem;
  --shot-shadow:
    0 1px 2px color-mix(in srgb, var(--text) 8%, transparent),
    0 16px 32px -14px color-mix(in srgb, var(--text) 30%, transparent),
    0 32px 56px -28px color-mix(in srgb, var(--accent) 24%, transparent);
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  color: var(--text);
  background:
    radial-gradient(ellipse 55% 42% at 8% -4%, var(--hp-glow), transparent 58%),
    radial-gradient(ellipse 42% 36% at 96% 8%, color-mix(in srgb, var(--accent-light) 42%, transparent), transparent 52%),
    var(--bg);
  overflow-x: hidden;
  overflow-x: clip;
  font-family: var(--hp-text);
}

.homepage[data-theme="dark"] {
  --hp-glow: color-mix(in srgb, var(--accent) 18%, transparent);
  --shot-shadow:
    0 1px 2px rgba(0, 0, 0, 0.4),
    0 18px 36px -14px rgba(0, 0, 0, 0.55),
    0 34px 60px -30px color-mix(in srgb, var(--accent) 28%, transparent);
}

/* Phone shell — original fill layout: thin black bezel, screenshot fills the screen */
.shot {
  display: block;
  width: 100%;
  height: auto;
  border: 0;
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}

.device {
  --device-radius: 1.85rem;
  --device-bezel: 0.22rem;
  --device-bezel-top: 0.22rem;
  --device-ratio: 440 / 956;
  --device-shell: #000;
  --device-island-h: 0.9rem;
  --device-island-w: 30%;
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: var(--device-ratio);
  padding: var(--device-bezel-top) var(--device-bezel) var(--device-bezel);
  border-radius: var(--device-radius);
  background: var(--device-shell);
  box-shadow:
    0 0 0 0.5px rgba(255, 255, 255, 0.1) inset,
    0 14px 32px -16px color-mix(in srgb, var(--text) 34%, transparent),
    0 28px 50px -28px color-mix(in srgb, var(--accent) 18%, transparent);
  transition: transform 0.5s var(--ease), box-shadow 0.5s var(--ease);
}

.device--sm,
.device--md,
.device--demo {
  --device-radius: 1.85rem;
  --device-bezel: 0.22rem;
  --device-bezel-top: 0.22rem;
}

.device--md { width: min(100%, 210px); }

.device--demo {
  width: min(100%, 280px);
  margin-inline: auto;
}

.device--xs {
  --device-radius: 1.4rem;
  --device-bezel: 0.18rem;
  --device-bezel-top: 0.18rem;
  --device-island-h: 0.7rem;
  width: min(100%, 124px);
}

.homepage[data-theme="light"] .device,
.homepage[data-theme="sepia"] .device,
.homepage[data-theme="dark"] .device,
.homepage:not([data-theme]) .device {
  --device-shell: #000;
}

.device__island {
  position: absolute;
  top: calc(var(--device-bezel-top) + 0.32rem);
  left: 50%;
  z-index: 4;
  width: var(--device-island-w);
  max-width: 5.6rem;
  height: var(--device-island-h);
  transform: translateX(-50%);
  border-radius: 999px;
  background: #000;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.06);
  pointer-events: none;
}

.device__screen {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 100%;
  border-radius: calc(var(--device-radius) - var(--device-bezel));
  background: #0a0a0a;
  isolation: isolate;
  /* Keep screenshots sharp even if an ancestor animates */
  filter: none !important;
  -webkit-mask-image: none;
  mask-image: none;
}

.device__screen .shot,
.device__screen .demo__shot,
.device__screen video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top center;
  border: 0;
  border-radius: 0;
  filter: none !important;
  transform: none;
  opacity: 1;
}

.device:hover {
  transform: translateY(-4px);
  box-shadow:
    0 0 0 0.5px rgba(255, 255, 255, 0.12) inset,
    0 20px 38px -16px color-mix(in srgb, var(--text) 40%, transparent),
    0 34px 58px -28px color-mix(in srgb, var(--accent) 22%, transparent);
}








/* Consistent section rhythm */
.homepage > section {
  scroll-margin-top: 1rem;
}

.homepage .section-head {
  margin-bottom: clamp(1.4rem, 2.8vw, 2rem);
}

.homepage .section-title {
  margin: 0 0 0.5rem;
  font-family: var(--hp-display);
  font-size: clamp(1.45rem, 2.5vw, 1.95rem);
  font-weight: 550;
  letter-spacing: -0.022em;
  line-height: 1.22;
  color: var(--hp-heading, var(--text));
}


/* Reveal motion — opacity/transform only (filter:blur on parents softens mockup screenshots) */
[data-reveal] {
  opacity: 0;
  transform: translateY(2rem);
  transition:
    opacity 0.8s var(--ease),
    transform 0.8s var(--ease);
  transition-delay: var(--stagger, var(--delay, 0ms));
}

[data-reveal="left"] {
  transform: translateX(-2.25rem) translateY(0.5rem);
}

[data-reveal="right"] {
  transform: translateX(2.5rem) scale(0.96);
}

[data-reveal].is-in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  [data-reveal],
  .shot,
  .hero__fan-item,
  .btn {
    transition: none !important;
    animation: none !important;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
  }
}

.wrap {
  width: min(1080px, 100%);
  margin-inline: auto;
  padding: clamp(1.35rem, 2.8vw, 2.2rem) clamp(1rem, 3.5vw, 1.75rem);
}

.wrap--tight {
  padding-block: clamp(1rem, 2vw, 1.35rem);
}

.section-head {
  text-align: center;
  margin-bottom: clamp(1.15rem, 2.4vw, 1.55rem);
}

.section-kicker {
  display: inline-flex;
  margin: 0 auto 0.45rem;
  padding: 0.28rem 0.75rem;
  border-radius: 999px;
  border: 1px solid var(--hp-border);
  background: var(--accent-light);
  color: var(--accent-strong);
  font-size: 0.7rem;
  font-weight: 750;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.section-kicker--left {
  margin-inline: 0;
}

.section-title {
  margin: 0 0 0.55rem;
  font-family: var(--hp-display);
  font-size: clamp(1.45rem, 2.6vw, 2rem);
  font-weight: 550;
  letter-spacing: -0.022em;
  line-height: 1.22;
  color: var(--hp-heading);
}

.section-sub {
  margin: 0 auto;
  max-width: 36rem;
  font-family: var(--hp-text);
  color: var(--hp-muted);
  font-size: clamp(0.98rem, 1.35vw, 1.08rem);
  line-height: 1.6;
  font-weight: 400;
}

.section-cta {
  display: flex;
  justify-content: center;
  margin-top: 1.2rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  padding: 0.65rem 1.15rem;
  border-radius: 0.8rem;
  border: 1px solid transparent;
  font-family: var(--hp-text);
  font-weight: 550;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.25s var(--ease), box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease, color 0.25s ease;
}

.btn--primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  color: var(--text-on-accent);
  box-shadow: 0 10px 22px -14px color-mix(in srgb, var(--accent) 60%, transparent);
  min-height: 3rem;
  padding-inline: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;

}

.btn--primary:hover {
  transform: translateY(-2px);
  color: var(--text-on-accent);
  box-shadow: 0 16px 28px -14px color-mix(in srgb, var(--accent) 65%, transparent);
}

.btn--secondary {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
  min-height: 3rem;
  padding-inline: 1.25rem;
  background: color-mix(in srgb, var(--surface-strong, var(--surface)) 88%, transparent);
  border-color: color-mix(in srgb, var(--border) 88%, transparent);

}

.btn--secondary:hover {
  background: color-mix(in srgb, var(--surface-strong, var(--surface)) 94%, var(--text-muted));
  border-color: color-mix(in srgb, var(--border) 62%, var(--text-muted));
  color: var(--text);
}

.btn:focus-visible,
.demo__toggle:focus-visible,
.demo__rail-btn:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 58%, #fff);
  outline-offset: 3px;
}

/* Hero */
.hero {
  position: relative;
  padding: clamp(1.4rem, 3.2vw, 2.6rem) clamp(1rem, 3.5vw, 1.75rem) clamp(1.8rem, 3.4vw, 2.8rem);
  overflow: hidden;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--surface-strong) 72%, transparent) 0%, transparent 68%),
    radial-gradient(ellipse 48% 55% at 78% 42%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 70%);
}

.hero__glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse 48% 55% at 78% 45%, var(--hp-glow), transparent 70%);
  animation: glow-pulse 9s ease-in-out infinite alternate;
  opacity: 0.85;
}

@keyframes glow-pulse {
  from { opacity: 0.55; transform: scale(1); }
  to { opacity: 1; transform: scale(1.05); }
}

.hero__inner {
  position: relative;
  z-index: 1;
  width: min(1120px, 100%);
  margin-inline: auto;
}

.hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: clamp(1.2rem, 3.5vw, 2.75rem);
  align-items: center;
}

.hero__copy {
  display: grid;
  gap: clamp(0.85rem, 1.5vw, 1.15rem);
  justify-items: start;
  text-align: start;
}

.hero__title {
  margin: 0;
  max-width: 20ch;
  font-family: var(--hp-display);
  font-size: clamp(1.85rem, 3.4vw, 2.55rem);
  font-weight: 550;
  line-height: 1.22;
  letter-spacing: -0.025em;
  color: var(--text);
}

.hero__desc {
  margin: 0;
  max-width: 40ch;
  font-family: var(--hp-text);
  font-size: clamp(1rem, 1.5vw, 1.12rem);
  font-weight: 400;
  line-height: 1.65;
  color: color-mix(in srgb, var(--text) 78%, var(--text-muted));
}

.hero__desc--mobile,
.hero__availability-compact,
.how__audience {
  display: none;
}

.hero__recite {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  max-width: 32rem;
  margin: 0;
  padding: 0.75rem 0.9rem;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border));
  border-radius: 0.85rem;
  background: color-mix(in srgb, var(--accent-light) 34%, var(--surface-strong));
  color: var(--text);
  font-size: clamp(0.92rem, 1.08vw, 1rem);
  line-height: 1.5;
  text-align: start;
}

.hero__recite i {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 15%, transparent);
  color: var(--accent-strong);
  font-size: 1.1rem;
}

.hero__audience {
  display: inline-flex;
  align-items: flex-start;
  gap: 0.5rem;
  max-width: 42rem;
  margin: 0;
  color: var(--hp-muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.hero__audience i {
  flex: 0 0 auto;
  margin-top: 0.16rem;
  color: var(--accent-strong);
}

.hero__availability {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  max-width: 34rem;
  color: var(--hp-muted);
}

.hero__availability > i {
  margin-top: 0.1rem;
  color: #188056;
  font-size: 1.1rem;
}

.hero__availability div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 0.5rem;
}

.hero__availability strong {
  color: var(--hp-heading);
  font-size: 0.9rem;
  font-weight: 750;
}

.hero__availability span {
  font-size: 0.84rem;
  line-height: 1.45;
}

.hero__availability--early > i { color: var(--accent-strong); }

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.hero__actions .btn {
  min-height: 3.3rem;
  padding-inline: 1.35rem;
  border-radius: 999px;
  font-size: 1rem;
  font-weight: 680;
}

.hero__actions .btn--primary {
  padding-inline: 1.55rem;
  box-shadow: 0 14px 28px -16px color-mix(in srgb, var(--accent-strong) 78%, transparent);
}

.hero__actions .btn--secondary {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--border));
  background: color-mix(in srgb, var(--surface-strong, var(--surface)) 72%, transparent);
  font-weight: 620;
}

.hero__visual {
  display: grid;
  min-width: 0;
  gap: 0.55rem;
}

.hero__visual-note {
  display: grid;
  gap: 0.2rem;
  justify-self: center;
  width: min(100%, 27rem);
  padding: 0.5rem 0.75rem;
  text-align: center;
}

.hero__visual-note span {
  color: var(--accent-strong);
  font-size: 0.67rem;
  font-weight: 780;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.hero__visual-note strong {
  color: var(--hp-heading);
  font-size: 0.82rem;
  font-weight: 680;
  line-height: 1.35;
}

.hero__fan {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;
  justify-items: center;
  width: 100%;
  min-height: clamp(280px, 44vw, 420px);
  perspective: 1100px;
}

.hero__fan-item {
  margin: 0;
  width: min(100%, 200px);
  will-change: transform;
}

.hero__fan-item--left {
  z-index: 1;
  transform: translate(16%, 10%) rotate(-8deg) scale(0.88);
  animation: float-y 6.4s ease-in-out infinite;
}

.hero__fan-item--center {
  z-index: 3;
  width: min(100%, 230px);
  transform: translateY(0) scale(1.04);
  animation: float-y 5.6s ease-in-out infinite 0.35s;
}

.hero__fan-item--right {
  z-index: 2;
  transform: translate(-16%, 10%) rotate(8deg) scale(0.88);
  animation: float-y 7s ease-in-out infinite 0.7s;
}

.hero__fan-item:hover .device {
  transform: translateY(-6px) scale(1.02);
}

@keyframes float-y {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -10px; }
}


/* Product walkthrough */
.demo {
  position: relative;
  overflow: clip;
  padding-block: clamp(0.35rem, 1.4vw, 0.9rem);
  background: transparent;
}

.demo__stage {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(1.25rem, 3vw, 2.25rem);
  align-items: center;
}

.demo__phone {
  position: relative;
  display: grid;
  justify-items: center;
}

.demo__phone::before {
  content: "";
  position: absolute;
  width: 72%;
  height: 42%;
  bottom: 8%;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 22%, transparent), transparent 72%);
  filter: blur(22px);
  z-index: 0;
  animation: demo-aura 5.5s ease-in-out infinite alternate;
  pointer-events: none;
}

@keyframes demo-aura {
  from { opacity: 0.45; transform: scale(0.92); }
  to { opacity: 0.9; transform: scale(1.08); }
}

.demo__phone .device {
  position: relative;
  z-index: 1;
  animation: demo-float 6.5s ease-in-out infinite;
}

@keyframes demo-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

.demo__story {
  display: grid;
  gap: 0.85rem;
  align-content: start;
  min-width: 0;
}

.demo__phase {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 780;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-strong, var(--accent));
}

.demo__headline {
  margin: 0;
  font-family: var(--hp-display);
  font-size: clamp(1.25rem, 2.2vw, 1.65rem);
  font-weight: 550;
  letter-spacing: -0.022em;
  line-height: 1.25;
  color: var(--hp-heading, var(--text));
}

.demo__body {
  margin: 0;
  max-width: 36ch;
  font-family: var(--hp-text);
  font-size: 0.98rem;
  font-weight: 400;
  line-height: 1.6;
  color: var(--hp-muted, var(--text-muted));
}

.demo__chrome {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  width: min(100%, 22rem);
  margin-top: 0.15rem;
}

.demo__toggle {
  flex: 0 0 auto;
  width: 2.7rem;
  height: 2.7rem;
  border: 0;
  border-radius: 999px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--text-on-accent, #fff);
  background: color-mix(in srgb, var(--accent) 94%, #000);
  box-shadow: 0 12px 24px -12px color-mix(in srgb, var(--accent) 55%, transparent);
  transition: transform 0.28s var(--ease), box-shadow 0.28s ease;
}

.demo__toggle:hover {
  transform: scale(1.07);
}

.demo__toggle i { font-size: 1.15rem; line-height: 1; }

.demo__progress {
  flex: 1;
  height: 0.38rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 10%, transparent);
  overflow: hidden;
}

.demo__progress-bar {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent), color-mix(in srgb, var(--accent) 65%, #fff));
  transition: width 0.35s linear;
}

.demo__rail {
  list-style: none;
  margin: 0.35rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.35rem;
}

.demo__rail-btn {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.7rem;
  align-items: center;
  text-align: start;
  padding: 0.62rem 0.75rem;
  border-radius: 0.85rem;
  border: 1px solid transparent;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background 0.35s var(--ease), border-color 0.35s var(--ease), transform 0.35s var(--ease), box-shadow 0.35s var(--ease);
}

.demo__rail-item.is-active .demo__rail-btn {
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border));
  background: color-mix(in srgb, var(--accent-light, var(--accent)) 22%, var(--surface-strong, var(--surface)));
  box-shadow: 0 12px 26px -18px color-mix(in srgb, var(--accent) 50%, transparent);
  transform: translateX(5px);
}

.demo__rail-item.is-done .demo__rail-num {
  background: color-mix(in srgb, var(--accent) 72%, #111);
  color: #fff;
}

.demo__rail-num {
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 0.78rem;
  font-weight: 800;
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-strong, var(--surface)));
  color: var(--accent-strong, var(--accent));
  transition: transform 0.35s var(--ease), background 0.35s ease, color 0.35s ease;
}

.demo__rail-item.is-active .demo__rail-num {
  background: var(--accent);
  color: var(--text-on-accent, #fff);
  transform: scale(1.08);
}

.demo__rail-label {
  font-size: 0.92rem;
  font-weight: 650;
  color: var(--hp-heading, var(--text));
}

.demo-fade-enter-active,
.demo-fade-leave-active {
  transition: opacity 0.35s var(--ease), transform 0.35s var(--ease);
}

.demo-fade-enter-from {
  opacity: 0;
  transform: translateY(8px) scale(0.985);
}

.demo-fade-leave-to {
  opacity: 0;
  transform: translateY(-6px) scale(0.99);
}

.demo__shot { background: #111; }

html[dir="rtl"] .demo__rail-item.is-active .demo__rail-btn {
  transform: translateX(-5px);
}

@media (max-width: 991.98px) {
  .demo__stage {
    grid-template-columns: minmax(0, 1fr);
    gap: 1.15rem;
  }

  .demo__story {
    order: 1;
    justify-items: stretch;
    text-align: center;
  }

  .demo__phone { order: 2; }

  .demo__body {
    max-width: 42ch;
    margin-inline: auto;
  }

