/* Steps / Your path */
.steps {
  border-block: 1px solid color-mix(in srgb, var(--border) 70%, transparent);
  background: color-mix(in srgb, var(--accent-light) 10%, transparent);
}

.steps__track {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  position: relative;
}

.steps__track::before {
  content: "";
  position: absolute;
  top: 4.6rem;
  left: 12%;
  right: 12%;
  height: 2px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent) 35%, var(--border)), transparent);
  pointer-events: none;
}

.steps__card {
  display: grid;
  gap: 0.85rem;
  justify-items: center;
  text-align: center;
  padding: 1rem 0.75rem 1.15rem;
  border-radius: 1.15rem;
  border: 1px solid color-mix(in srgb, var(--accent) 14%, var(--border));
  background: color-mix(in srgb, var(--surface-strong) 92%, transparent);
  min-width: 0;
  transition: transform 0.4s var(--ease), box-shadow 0.4s var(--ease), border-color 0.4s ease;
  animation: steps-rise 0.7s var(--ease) both;
  animation-delay: var(--delay, 0ms);
}

.steps__card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border));
  box-shadow: 0 16px 28px -20px color-mix(in srgb, var(--text) 30%, transparent);
}

@keyframes steps-rise {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: none; }
}

.steps__visual {
  position: relative;
  z-index: 1;
  width: min(100%, 140px);
}

.steps__body {
  display: grid;
  gap: 0.3rem;
  justify-items: center;
}

.steps__num {
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: var(--accent);
  color: var(--text-on-accent);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.steps__body h3 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 730;
  color: var(--hp-heading);
}

.steps__body p {
  margin: 0;
  max-width: 28ch;
