}

.faq__accordion .accordion-body {
  color: var(--hp-muted);
  line-height: 1.55;
  padding: 0.55rem 0.95rem 0.9rem;
  font-size: 0.9rem;
}

/* Contact — clean and compact */
.contact {
  padding-block: 0.25rem;
}

.wrap--narrow {
  width: min(560px, 100%);
  margin-inline: auto;
  padding: clamp(1.2rem, 2.5vw, 1.75rem) clamp(1rem, 3.5vw, 1.75rem);
