/* Tablet portrait: space between hero CTAs and device mockup */
@media (min-width: 768px) and (max-width: 1024px) and (orientation: portrait) {
  .hero__actions {
    margin-bottom: clamp(1.35rem, 3.8vw, 2.35rem);
    padding-bottom: clamp(0.25rem, 1vw, 0.65rem);
  }
}

/* Responsive */
@media (max-width: 991.98px) {
  .hero__grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 1.35rem;
  }

  .hero__copy { order: 0; }
  .hero__visual { order: 1; }

  .hero__copy {
    justify-items: center;
    text-align: center;
  }

  .hero__title { max-width: none; }
  .hero__desc { max-width: 42ch; }
  .hero__audience { justify-content: center; text-align: center; }
  .hero__availability { text-align: start; }
  .hero__actions { justify-content: center; }

  .practice-types__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .how__row,
  .how__row--flip {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }

  .how__row--flip .how__copy,
  .how__row--flip .how__shot { order: initial; }

  .how__copy { order: 0; }
  .how__shot { order: 1; }

  .features__grid { grid-template-columns: minmax(0, 1fr); }

  .waitlist__band { grid-template-columns: minmax(0, 1fr); }
  .waitlist__band .btn { width: 100%; }
}

/* Tablet portrait: two feature cards per row (Bootstrap col-md-6). */
@media (min-width: 768px) and (max-width: 1366px) and (orientation: portrait) {
  .homepage .features__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.85rem;
  }

  .homepage .features__item {
    min-width: 0;
  }

  .homepage .features__device {
    flex-basis: 128px;
    width: 128px;
    max-width: 38%;
  }
}

@media (max-width: 767.98px) {
  .steps__track {
    grid-template-columns: minmax(0, 1fr);
  }

  .steps__track::before { display: none; }

  .contact__grid { grid-template-columns: minmax(0, 1fr); }

  .hero__fan {
    min-height: clamp(220px, 72vw, 320px);
    width: min(100%, 400px);
    margin-inline: auto;
  }

  .hero__fan-item--left {
    transform: translate(20%, 12%) rotate(-7deg) scale(0.82);
  }

  .hero__fan-item--right {
    transform: translate(-20%, 12%) rotate(7deg) scale(0.82);
  }

  .hero__actions {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    width: 100%;
  }

  .hero__actions .btn { width: 100%; }

  .practice-types__grid { grid-template-columns: minmax(0, 1fr); }

  .session-brief { grid-template-columns: minmax(0, 1fr); }

  .session-brief__item {
    min-height: 0;
    padding: 1rem 1.15rem;
    border-inline-end: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--accent) 12%, var(--border));
  }

  .session-brief__item:last-child { border-bottom: 0; }

  .features__item {
    gap: 0.95rem;
    padding: 0.95rem 1rem;
  }

  .features__device {
    flex-basis: 136px;
    width: 136px;
  }

  .steps__list { grid-template-columns: minmax(0, 1fr); }

  .contact__row { grid-template-columns: minmax(0, 1fr); }

  .footer__grid { grid-template-columns: minmax(0, 1fr); }

  .footer {
    padding-bottom: 1.65rem;
  }

  .footer__bottom {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "tagline"
      "social"
      "copy";
    justify-items: start;
    padding-bottom: 0.65rem;
  }

  .footer__tagline {
    grid-area: tagline;
    white-space: normal;
    overflow: visible;
    text-overflow: unset;
  }

  .footer__copy {
    grid-area: copy;
    justify-self: center;
  }

  .footer__social {
    grid-area: social;
    justify-self: start;
    justify-content: flex-start;
  }
}

@media (min-width: 560px) and (max-width: 767.98px) {
  .steps__list { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

html[dir="rtl"] .hero__fan-item--left {
  transform: translate(-16%, 10%) rotate(8deg) scale(0.88);
}

html[dir="rtl"] .hero__fan-item--right {
  transform: translate(16%, 10%) rotate(-8deg) scale(0.88);
}



@keyframes hero-fan-drift {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -12px; }
}

.hero__fan-item--left,
.hero__fan-item--center,
.hero__fan-item--right {
  animation: hero-fan-drift 6.2s ease-in-out infinite;
}

.hero__fan-item--center { animation-delay: 0.25s; }
.hero__fan-item--right { animation-delay: 0.55s; }

.hero__availability {
  animation: promise-in 0.9s var(--ease) both;
  animation-delay: 0.15s;
}

@keyframes promise-in {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .hero__fan-item--left,
  .hero__fan-item--center,
  .hero__fan-item--right,
  .hero__availability { animation: none !important; }
}

/* Premium mobile rhythm */
@media (max-width: 767.98px) {
  /* Keep decorative layers still while the user scrolls on a phone. */
  .hero__glow,
  .hero__fan-item,
  .demo__phone::before,
  .demo__phone .device {
    animation: none !important;
    will-change: auto;
  }

  .demo__phone::before {
    filter: none;
  }

  .hero__fan {
    perspective: none;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .hero {
    padding-top: 1.1rem;
    padding-bottom: 1.5rem;
  }

  .hero__grid { gap: 1rem; }

  .hero__copy {
    grid-template-columns: minmax(0, max-content) minmax(0, max-content);
    justify-content: center;
    gap: 0.65rem 0.9rem;
  }

  .hero__title,
  .hero__desc--mobile,
  .hero__actions .btn--primary {
    grid-column: 1 / -1;
  }

  .hero__desc--desktop,
  .hero__recite,
  .hero__audience,
  .hero__visual-note {
    display: none;
  }

  .hero__desc--mobile { display: block; }

  .hero__actions { display: contents; }

  .hero__actions .btn--primary {
    width: min(100%, 20rem);
    min-height: 3.1rem;
    margin-top: 0.2rem;
  }

  .hero__actions .btn--secondary {
    grid-column: 2;
    grid-row: 4;
    width: auto;
    min-height: 2.75rem;
    padding: 0 0.25rem;
    border: 0;
    background: transparent;
    box-shadow: none;
    color: var(--text);
    font-size: 0.9rem;
    text-decoration: underline;
    text-decoration-color: var(--accent);
    text-underline-offset: 0.18em;
    white-space: normal;
  }

  .hero__actions .btn--secondary i { display: none; }

  .hero__availability {
    grid-column: 1;
    grid-row: 4;
    align-items: center;
    justify-self: end;
    gap: 0.35rem;
    animation: none;
  }

  .hero__availability:not(.hero__availability--early) strong,
  .hero__availability:not(.hero__availability--early) .hero__availability-detail {
    display: none;
  }

  .hero__availability-compact { display: inline; }

  .hero__availability--early {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .hero__visual { gap: 0; }
  .hero__fan { min-height: 0; }

  .hero__title {
    font-size: clamp(1.65rem, 6.6vw, 2.05rem);
    line-height: 1.24;
    max-width: 18ch;
    margin-inline: auto;
  }

  .hero__desc {
    max-width: 36ch;
    margin-inline: auto;
    line-height: 1.5;
  }

  .how__audience {
    display: block;
    max-width: 36rem;
    margin: 0.8rem auto 0;
    color: var(--hp-muted);
    font-size: 0.9rem;
    line-height: 1.5;
  }

  .purpose__card {
    padding: 1.15rem 1rem 1.25rem;
  }

  .purpose__card .section-title {
    font-size: 1.35rem;
  }

  .closing__card {
    padding: 1.4rem 1.05rem 1.5rem;
  }

  .closing__title {
    font-size: 1.45rem;
  }

  .closing__actions,
  .closing__actions .btn {
    width: 100%;
  }

  .section-head { margin-bottom: 1.5rem; }

  .demo__headline {
    font-size: 1.35rem;
    font-weight: 550;
    line-height: 1.25;
  }
}
